// SPDX-License-Identifier: BUSL-1.1
pragma solidity ^0.8.20;

import {IERC4626} from "@openzeppelin/contracts/interfaces/IERC4626.sol";
import {IERC20} from "@openzeppelin/contracts/interfaces/IERC20.sol";

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import {Address} from "@openzeppelin/contracts/utils/Address.sol";

import {FIFOQueue} from "../lib/FIFOQueue.sol";
import {Errors} from "../lib/Errors.sol";
import {OperatorSettable} from "../lib/OperatorSettable.sol";
import {GranularPause} from "../lib/GranularPause.sol";
import {SharedDepositMinterV2} from "./SharedDepositMinterV2.sol";

/**
 * @title WithdrawalQueue
 * @author @ChimeraDefi - chimera_defi@protonmail.com | sharedstake.org
 * @dev -
 * ERC-7540 inspired withdrawal contract
 * This contract is designed to be used with SharedDepositMinterV2 contract
 * As a module extension that adds 7540 methods requestRedeem and redeem
 * Example flow ->
 * user calls requestRedeem(user, user, userShares)
 * user calls setOperator(admin OR protocol provided keeper, true)
 * admin can now call redeem on the users behalf if needed after epoch
 * user calls redeem(user, user, userShares) after waiting for epoch
 * Caveats:
 * If the user requests another redemption, before fulfillment,
 * this resets the epoch length clock for their request
 * Basic upgrade path:
 * 1. Call togglePause(1), this disables the requestRedeem fn so no new requests
 * 2. Deploy new contract, direct users to it
 * 3. Fulfill any remaining redeemRequests i.e. totalPendingRequest,
 * for all RedeemRequest events from requestsFulfilled to requestsCreated
 */
contract WithdrawalQueue is AccessControl, ReentrancyGuard, GranularPause, FIFOQueue, OperatorSettable {
    using Address for address payable;

    struct Request {
        address requester;
        uint256 shares;
    }
    // SharedDepositMinterV2 public immutable MINTER;
    address public immutable MINTER;
    address public immutable WSGETH;

    uint256 internal totalPendingRequest;
    uint256 internal requestsCreated;
    uint256 internal requestsFulfilled;
    uint256 public totalAssetsOut;

    bytes32 public constant GOV = keccak256("GOV"); // Governance for settings - normally timelock controlled by multisig

    mapping(uint256 => Request) internal requests;
    mapping(address => uint256) public redeemRequests;

    event RedeemRequest(
        address indexed requester,
        address indexed owner,
        uint256 indexed requestId,
        address operator,
        uint256 assets
    );
    event Redeem(address indexed requester, address indexed receiver, uint256 shares, uint256 assets);
    event CancelRedeem(address indexed requester, address indexed receiver, uint256 shares, uint256 assets);

    constructor(address _minter, address _wsgEth, uint256 _epochLength, address _governance) FIFOQueue(_epochLength) {
        if (_minter == address(0) || _wsgEth == address(0) || _governance == address(0)) {
            revert Errors.ZeroAddress();
        }

        MINTER = _minter;
        WSGETH = _wsgEth;

        uint256 maxUint256 = 2 ** 256 - 1;

        IERC20(WSGETH).approve(_minter, maxUint256);

        _grantRole(GOV, _governance);
    }

    /// @notice Requests a redemption of vault assets.
    /// @dev This function must be called by either the owner or an operator of the vault, and is only allowed when the contract is not paused.

    /// @param shares The number of shares to redeem.
    /// @param requester The address requesting the redemption.
    /// @param owner The owner of the vault being redeemed from.

    /// @return requestId The unique ID assigned to this redemption request.
    function requestRedeem(
        uint256 shares,
        address requester,
        address owner
    ) external onlyOwnerOrOperator(owner) nonReentrant whenNotPaused(uint16(1)) returns (uint256 requestId) {
        if (shares == 0) {
            revert Errors.InvalidAmount();
        }
        IERC20(WSGETH).transferFrom(owner, address(this), shares); // asset here is the Vault underlying asset

        requestId = requestsCreated++;
        requests[requestId] = Request({requester: requester, shares: shares});
        // use assets for tracking
        uint256 assets = IERC4626(WSGETH).previewRedeem(shares);

        _stakeForWithdrawal(owner, assets);
        totalPendingRequest += assets;
        redeemRequests[requester] += assets; // underflow would revert if not enough claimable shares

        emit RedeemRequest(requester, owner, requestId, msg.sender, shares);
    }

    /// @notice Allows a user to redeem their vault shares.
    /// @dev This function must be called by either the owner or an operator of the requester's vault, and is only allowed when the contract is not paused.

    /// @param shares The number of shares to redeem.
    /// @param receiver The address that will receive the redeemed assets.
    /// @param requester The address requesting the redemption.

    /// @return assets The amount of assets that were successfully redeemed.
    function redeem(
        uint256 shares,
        address receiver,
        address requester
    ) external onlyOwnerOrOperator(requester) nonReentrant whenNotPaused(uint16(2)) returns (uint256 assets) {
        if (shares == 0) {
            revert Errors.InvalidAmount();
        }

        assets = IERC4626(WSGETH).previewRedeem(shares);

        // checks if we have enough assets to fulfill the request and if epoch has passed
        if (claimableRedeemRequest(requester) < assets) {
            _checkWithdraw(requester, totalBalance(), assets);
            return 0; // should never happen. previous fn will generate a rich error
        }

        _withdraw(requester, assets);
        // Treat everything as claimableRedeemRequest and validate here if there's adequate funds
        redeemRequests[requester] -= assets; // underflow would revert if not enough claimable shares
        totalPendingRequest -= assets;
        // Track total returned
        totalAssetsOut += assets;
        requestsFulfilled++;

        uint256 minterBalance = MINTER.balance;
        // This feels suboptimal, but is the easiest way to always burn the token on redemptions
        if (assets > minterBalance) {
            uint256 diff = assets - minterBalance;
            // We need to use donate/transfer etc. cant deposit and mint more shares as that messes up accouting
            payable(MINTER).transfer(diff);
        }

        // Always burn redeemed tokens
        SharedDepositMinterV2(payable(MINTER)).unstakeAndWithdraw(shares, receiver);

        emit Redeem(requester, receiver, shares, assets);
    }

    /// @notice Cancel a redeem request and return funds to owner. Can only be done after the epoch has expired
    function cancelRedeem(
        address receiver,
        address requester
    ) external onlyOwnerOrOperator(requester) nonReentrant whenNotPaused(uint16(3)) returns (uint256 assets) {
        uint256 shares = pendingRedeemRequest(requester);
        assets = IERC4626(WSGETH).previewRedeem(shares);

        if (shares == 0) {
            revert Errors.InvalidAmount();
        }

        _verifyEpochHasElapsed(requester);

        // checks if we have enough assets to fulfill the request and if epoch has passed
        if (claimableRedeemRequest(requester) < assets) {
            _checkWithdraw(requester, totalBalance(), assets);
            return 0; // should never happen. previous fn will generate a rich error
        }

        // Treat everything as claimableRedeemRequest and validate here if there's adequate funds
        redeemRequests[requester] -= assets; // underflow would revert if not enough claimable shares
        totalPendingRequest -= assets;
        _withdraw(requester, assets);
        IERC20(WSGETH).transfer(receiver, shares); // asset here is the Vault underlying asset

        emit CancelRedeem(requester, receiver, shares, assets);
    }

    function togglePause(uint16 func) external onlyRole(GOV) {
        bool paused = paused[func];
        if (paused) {
            _unpause(func);
        } else {
            _pause(func);
        }
    }

    function setEpochLength(uint256 value) external onlyRole(GOV) {
        _setEpochLength(value);
    }

    function pendingRedeemRequest(address owner) public view returns (uint256 shares) {
        return redeemRequests[owner];
    }

    // claimableRedeemRequest - returns owners shares in claimable state,
    // i.e. epoch has elapsed and sufficient funds exist
    function claimableRedeemRequest(address owner) public view returns (uint256 shares) {
        if (redeemRequests[owner] > 0 && _isWithdrawalAllowed(owner, totalBalance(), redeemRequests[owner])) {
            return redeemRequests[owner];
        } else {
            return 0;
        }
    }

    function totalBalance() internal view returns (uint256) {
        return address(this).balance + MINTER.balance;
    }

    receive() external payable {} // solhint-disable-line

    fallback() external payable {} // solhint-disable-line
}

contracts/v2/governance/VoteEscrowV2.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";
import {ERC20Votes} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Votes.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Errors} from "../lib/Errors.sol";

/// @title VoteEscrowV2 — vote-escrowed SGT for SharedStake V2 governance
/// @notice Curve-style vote escrow that locks SGTv2 for decaying voting power.
///         Voting power is compatible with OpenZeppelin Governor (ERC20Votes).
///
///         Lock SGTv2 → receive veSGT voting power that decays linearly to 0
///         at lock expiry. Longer locks = more voting power per SGT locked.
///
///         Key difference from V1: voting power properly decays in ERC20Votes
///         checkpoints, enabling accurate on-chain governance voting.
///
/// Roles:
///   GOV — set params (penalty rate, min lock)
///   No owner after initial setup (renounced)
contract VoteEscrowV2 is ERC20, ERC20Permit, ERC20Votes, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ── Roles ─────────────────────────────────────────────────────────────────
    address public gov;

    // ── Constants ─────────────────────────────────────────────────────────────
    uint256 public constant MINDAYS = 7;
    uint256 public constant MAXDAYS = 3 * 365;
    uint256 public constant MAXTIME = MAXDAYS * 1 days;
    uint256 public constant MAX_WITHDRAWAL_PENALTY = 50000; // 50%
    uint256 public constant PRECISION = 100000;

    // ── Immutables ────────────────────────────────────────────────────────────
    IERC20 public immutable SGT;

    // ── State ─────────────────────────────────────────────────────────────────
    struct LockedBalance {
        uint256 amount;
        uint256 end;
    }

    uint256 public earlyWithdrawPenaltyRate = 30000; // 30%
    uint256 public minLockedAmount;
    address public penaltyCollector;

    mapping(address => LockedBalance) public locked;
    mapping(address => uint256) public mintedForLock;

    // ── Events ────────────────────────────────────────────────────────────────
    event Deposit(address indexed provider, uint256 value, uint256 locktime, uint256 timestamp);
    event Withdraw(address indexed provider, uint256 value, uint256 timestamp);
    event EarlyWithdraw(address indexed provider, uint256 value, uint256 fee, uint256 timestamp);
    event PenaltyCollectorSet(address indexed addr);
    event EarlyWithdrawPenaltySet(uint256 indexed penalty);
    event MinLockedAmountSet(uint256 indexed amount);
    event GovTransferred(address indexed oldGov, address indexed newGov);

    // ── Errors ────────────────────────────────────────────────────────────────
    error NothingToWithdraw();
    error LockNotExpired();
    error LessThanMinAmount();
    error WithdrawOldTokensFirst();
    error MinDaysTooShort();
    error MaxDaysTooLong();
    error CannotExtendBeyondMax();
    error NoBenefitToLock();
    error LockExpired();
    error PenaltyTooHigh();
    error ZeroAddress();
    error PermissionDenied();

    constructor(
        string memory _name,
        string memory _symbol,
        address _sgt,
        uint256 _minLockedAmount,
        address _gov
    ) ERC20(_name, _symbol) ERC20Permit(_name) {
        if (_sgt == address(0) || _gov == address(0)) revert ZeroAddress();
        SGT = IERC20(_sgt);
        minLockedAmount = _minLockedAmount;
        gov = _gov;
    }

    // ── Governance modifier ───────────────────────────────────────────────────
    modifier onlyGov() {
        if (msg.sender != gov) revert PermissionDenied();
        _;
    }

    // ── Locking ───────────────────────────────────────────────────────────────

    function create_lock(uint256 _value, uint256 _days) external nonReentrant {
        if (_value < minLockedAmount) revert LessThanMinAmount();
        if (locked[msg.sender].amount != 0) revert WithdrawOldTokensFirst();
        if (_days < MINDAYS) revert MinDaysTooShort();
        if (_days > MAXDAYS) revert MaxDaysTooLong();

        _deposit_for(msg.sender, _value, _days);
    }

    function increase_amount(uint256 _value) external nonReentrant {
        if (_value < minLockedAmount) revert LessThanMinAmount();
        _deposit_for(msg.sender, _value, 0);
    }

    function increase_unlock_time(uint256 _days) external nonReentrant {
        if (_days < MINDAYS) revert MinDaysTooShort();
        if (_days > MAXDAYS) revert MaxDaysTooLong();

        LockedBalance storage _locked = locked[msg.sender];
        if (_locked.amount == 0) revert NothingToWithdraw();
        if (block.timestamp >= _locked.end) revert LockExpired();

        uint256 _now = block.timestamp;
        uint256 _end = _locked.end;
        uint256 _amount = _locked.amount;

        // Cannot increase amount and extend lock simultaneously
        uint256 _vp = voting_power_locked_days(_amount, _days);
        _locked.end = _end + _days * 1 days;
        if (_locked.end - _now > MAXTIME) revert CannotExtendBeyondMax();

        if (_vp == 0) revert NoBenefitToLock();

        // Mint additional voting power for the extension
        _mint(msg.sender, _vp);
        mintedForLock[msg.sender] += _vp;

        emit Deposit(msg.sender, _locked.amount, _locked.end, _now);
    }

    function withdraw() external nonReentrant {
        LockedBalance storage _locked = locked[msg.sender];
        uint256 _now = block.timestamp;
        if (_locked.amount == 0) revert NothingToWithdraw();
        if (_now < _locked.end) revert LockNotExpired();

        uint256 _amount = _locked.amount;
        _locked.end = 0;
        _locked.amount = 0;

        uint256 _minted = mintedForLock[msg.sender];
        mintedForLock[msg.sender] = 0;
        _burn(msg.sender, _minted);

        SGT.safeTransfer(msg.sender, _amount);
        emit Withdraw(msg.sender, _amount, _now);
    }

    function emergencyWithdraw() external nonReentrant {
        LockedBalance storage _locked = locked[msg.sender];
        uint256 _now = block.timestamp;
        if (_locked.amount == 0) revert NothingToWithdraw();

        uint256 _amount = _locked.amount;
        if (_now < _locked.end) {
            uint256 _fee = (_amount * earlyWithdrawPenaltyRate) / PRECISION;
            _penalize(_fee);
            _amount -= _fee;
            emit EarlyWithdraw(msg.sender, _amount, _fee, _now);
        }

        _locked.end = 0;
        _locked.amount = 0;

        uint256 _minted = mintedForLock[msg.sender];
        mintedForLock[msg.sender] = 0;
        _burn(msg.sender, _minted);

        SGT.safeTransfer(msg.sender, _amount);
        emit Withdraw(msg.sender, _amount, _now);
    }

    // ── Admin (GOV only) ──────────────────────────────────────────────────────

    function setEarlyWithdrawPenaltyRate(uint256 _rate) external onlyGov {
        if (_rate > MAX_WITHDRAWAL_PENALTY) revert PenaltyTooHigh();
        earlyWithdrawPenaltyRate = _rate;
        emit EarlyWithdrawPenaltySet(_rate);
    }

    function setMinLockedAmount(uint256 _amount) external onlyGov {
        minLockedAmount = _amount;
        emit MinLockedAmountSet(_amount);
    }

    function setPenaltyCollector(address _addr) external onlyGov {
        penaltyCollector = _addr;
        emit PenaltyCollectorSet(_addr);
    }

    function transferGov(address _newGov) external onlyGov {
        if (_newGov == address(0)) revert ZeroAddress();
        address oldGov = gov;
        gov = _newGov;
        emit GovTransferred(oldGov, _newGov);
    }

    // ── Public views ──────────────────────────────────────────────────────────

    function voting_power_unlock_time(uint256 _value, uint256 _unlockTime) public view returns (uint256) {
        uint256 _now = block.timestamp;
        if (_unlockTime <= _now) return 0;
        uint256 _lockedSeconds = _unlockTime - _now;
        if (_lockedSeconds >= MAXTIME) {
            return _value;
        }
        return (_value * _lockedSeconds) / MAXTIME;
    }

    function voting_power_locked_days(uint256 _value, uint256 _days) public view returns (uint256) {
        if (_days >= MAXDAYS) {
            return _value;
        }
        return (_value * _days) / MAXDAYS;
    }

    // ── Internal ──────────────────────────────────────────────────────────────

    function _deposit_for(address _addr, uint256 _value, uint256 _days) internal {
        LockedBalance storage _locked = locked[_addr];
        uint256 _now = block.timestamp;
        uint256 _amount = _locked.amount;
        uint256 _end = _locked.end;
        uint256 _vp;
        if (_amount == 0) {
            _vp = voting_power_locked_days(_value, _days);
            _locked.amount = _value;
            _locked.end = _now + _days * 1 days;
        } else if (_days == 0) {
            _vp = voting_power_unlock_time(_value, _end);
            _locked.amount = _amount + _value;
        } else {
            // This path is unreachable from the external entry points,
            // but kept for internal consistency.
            _vp = voting_power_locked_days(_amount, _days);
            _locked.end = _end + _days * 1 days;
            if (_locked.end - _now > MAXTIME) revert CannotExtendBeyondMax();
        }
        if (_vp == 0) revert NoBenefitToLock();
        if (_value > 0) {
            SGT.safeTransferFrom(msg.sender, address(this), _value);
        }
        _mint(_addr, _vp);
        mintedForLock[_addr] += _vp;

        emit Deposit(_addr, _locked.amount, _locked.end, _now);
    }

    function _penalize(uint256 _amount) internal {
        if (penaltyCollector != address(0)) {
            SGT.safeTransfer(penaltyCollector, _amount);
        } else {
            // If no collector set, tokens are effectively burned by staying in contract
            // or could be sent to dead address via future gov action
            SGT.safeTransfer(address(0x000000000000000000000000000000000000dEaD), _amount);
        }
    }

    // ── ERC20Votes required overrides ─────────────────────────────────────────

    function _mint(address to, uint256 amount) internal override(ERC20, ERC20Votes) {
        super._mint(to, amount);
    }

    function _burn(address account, uint256 amount) internal override(ERC20, ERC20Votes) {
        super._burn(account, amount);
    }

    function _afterTokenTransfer(address from, address to, uint256 amount) internal override(ERC20, ERC20Votes) {
        super._afterTokenTransfer(from, to, amount);
    }
}

