// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

import {ValidatorModule} from "./ValidatorModule.sol";

/// @title DVTModule - Distributed Validator Technology variant of ValidatorModule
/// @notice Distributed Validator Technology (DVT — e.g. Obol, SSV) is a different
///         operator topology, not a different accounting model. The economic flow
///         (buffer ETH, push to beacon, oracle reports balance, router rebases)
///         is identical to a solo-validator setup. We override `moduleType()` so
///         off-chain tooling can distinguish DVT validators from solo, and reserve
///         this contract as the integration point for cluster-coordinator hooks
///         (operator whitelist, threshold-signature pre-flight, etc.) in Phase 2.
contract DVTModule is ValidatorModule {
    constructor(address router, bytes32 moduleId, address gov, address beaconDepositContract)
        ValidatorModule(router, moduleId, gov, beaconDepositContract)
    {}

    function moduleType() external pure override returns (bytes32) {
        return keccak256("DVT_VALIDATOR");
    }
}

contracts/v2/modular-staking/modules/LST.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IStakingRouter} from "../interfaces/IStakingRouter.sol";
import {IStakingModule} from "../interfaces/IStakingModule.sol";
import {ILSTPriceOracle} from "../interfaces/ILSTPriceOracle.sol";
import {GranularPause} from "../../lib/GranularPause.sol";
import {Errors} from "../../lib/Errors.sol";

/// @title LSTWrapModule - accept LSTs (stETH, rETH, etc.) and mint stToken
/// @notice Separate entry/exit path from the validator modules. Users deposit an
///         existing LST, get stToken backed by the ETH equivalent of that LST.
///         Exits go through this module's `unwrapLST` (NOT the withdrawal queue):
///         the contract burns stToken via the Router and returns LST 1-for-1 with
///         what the user originally locked.
///
///         This module's `totalEth()` is `priceOracle.getEthValue(_lstHeld)` so the
///         Router's mint cap can bound exposure to LST market depeg risk.
///
/// Roles:
///   GOV       — set price oracle, pause/unpause
///   GUARDIAN  — emergency pause
contract LSTWrapModule is AccessControl, ReentrancyGuard, GranularPause, IStakingModule {
    using SafeERC20 for IERC20;

    // ── Roles ─────────────────────────────────────────────────────────────────
    bytes32 public constant GOV = keccak256("GOV");
    bytes32 public constant GUARDIAN = keccak256("GUARDIAN");

    // ── Pause IDs ─────────────────────────────────────────────────────────────
    uint16 public constant PAUSE_WRAP = 0;
    uint16 public constant PAUSE_UNWRAP = 1;

    // ── Immutables ────────────────────────────────────────────────────────────
    IStakingRouter public immutable ROUTER;
    bytes32 public immutable MODULE_ID;
    IERC20 public immutable LST_TOKEN;

    // ── State ─────────────────────────────────────────────────────────────────
    ILSTPriceOracle public priceOracle;
    uint256 internal _lstHeld;

    /// @notice Maximum allowed age (seconds) of the price oracle's last update before
    ///         `wrapLST` reverts with `StaleOracle`. Default 3600 (1 hour).
    uint256 public maxOracleAgeSecs = 3600;

    // ── Events ────────────────────────────────────────────────────────────────
    event PriceOracleSet(address indexed oracle);
    event LstWrapped(address indexed account, address indexed recipient, uint256 lstAmount, uint256 ethEquiv);
    event LstUnwrapped(address indexed account, address indexed recipient, uint256 stTokenAmount, uint256 lstAmount);
    event MaxOracleAgeSet(uint256 newValue);

    // ── Errors ────────────────────────────────────────────────────────────────
    error PriceOracleNotSet();
    error InsufficientLstHeld(uint256 requested, uint256 held);

    constructor(address router, bytes32 moduleId, address lstToken, address gov) {
        if (router == address(0) || lstToken == address(0) || gov == address(0)) {
            revert Errors.ZeroAddress();
        }
        if (moduleId == bytes32(0)) revert Errors.InvalidAmount();
        ROUTER = IStakingRouter(router);
        MODULE_ID = moduleId;
        LST_TOKEN = IERC20(lstToken);

        _grantRole(DEFAULT_ADMIN_ROLE, gov);
        _grantRole(GOV, gov);
        _grantRole(GUARDIAN, gov);
    }

    // ── User entry/exit ──────────────────────────────────────────────────────

    /// @notice Deposit `lstAmount` of the wrapped LST in exchange for stToken.
    ///         Caller must have approved this contract for at least `lstAmount`.
    /// @param recipient Address to receive the minted stToken.
    function wrapLST(uint256 lstAmount, address recipient)
        external
        nonReentrant
        whenNotPaused(PAUSE_WRAP)
        returns (uint256 ethEquiv)
    {
        if (lstAmount == 0) revert Errors.InvalidAmount();
        if (recipient == address(0)) revert Errors.ZeroAddress();
        if (address(priceOracle) == address(0)) revert PriceOracleNotSet();

        ethEquiv = priceOracle.getEthValue(lstAmount);
        if (ethEquiv == 0) revert Errors.InvalidAmount();
        // Reject stale oracle readings — protects against minting unbacked stToken
        // if an LST depegs and the oracle hasn't updated.
        if (block.timestamp - priceOracle.lastUpdated() > maxOracleAgeSecs) {
            revert Errors.StaleOracle();
        }

        // Pull LST in first so the router's totalEth() / mint-cap check sees the new balance.
        LST_TOKEN.safeTransferFrom(msg.sender, address(this), lstAmount);
        _lstHeld += lstAmount;

        // Router mints shares to recipient and (re)checks the cap.
        ROUTER.wrapFromModule(MODULE_ID, recipient, ethEquiv);

        emit LstWrapped(msg.sender, recipient, lstAmount, ethEquiv);
    }

    /// @notice Burn `stTokenAmount` of stToken and receive LST in return.
    ///         Caller must hold the stToken; the Router will burn it from `msg.sender`.
    function unwrapLST(uint256 stTokenAmount, address recipient)
        external
        nonReentrant
        whenNotPaused(PAUSE_UNWRAP)
        returns (uint256 lstAmount)
    {
        if (stTokenAmount == 0) revert Errors.InvalidAmount();
        if (recipient == address(0)) revert Errors.ZeroAddress();
        if (address(priceOracle) == address(0)) revert PriceOracleNotSet();

        // Router burns the stToken shares from msg.sender and tells us the ETH value.
        uint256 ethValue = ROUTER.unwrapToModule(MODULE_ID, msg.sender, stTokenAmount);

        lstAmount = priceOracle.getLstValue(ethValue);
        if (lstAmount == 0) revert Errors.InvalidAmount();
        if (lstAmount > _lstHeld) revert InsufficientLstHeld(lstAmount, _lstHeld);

        _lstHeld -= lstAmount;
        LST_TOKEN.safeTransfer(recipient, lstAmount);

        emit LstUnwrapped(msg.sender, recipient, stTokenAmount, lstAmount);
    }

    // ── IStakingModule surface ───────────────────────────────────────────────

    /// @inheritdoc IStakingModule
    /// @dev Disallowed: LST module never receives raw ETH from the Router. Reverts to
    ///      surface routing mistakes loudly rather than silently accepting funds.
    function receiveDeposit() external payable override {
        revert Errors.PermissionDenied();
    }

    /// @inheritdoc IStakingModule
    function totalEth() external view override returns (uint256) {
        if (address(priceOracle) == address(0) || _lstHeld == 0) return 0;
        return priceOracle.getEthValue(_lstHeld);
    }

    /// @inheritdoc IStakingModule
    function moduleType() external pure override returns (bytes32) {
        return keccak256("LST_WRAP");
    }

    // ── Admin ────────────────────────────────────────────────────────────────

    function setPriceOracle(address oracle) external onlyRole(GOV) {
        if (oracle == address(0)) revert Errors.ZeroAddress();
        priceOracle = ILSTPriceOracle(oracle);
        emit PriceOracleSet(oracle);
    }

    /// @notice Update the maximum tolerated price-oracle staleness (seconds).
    /// @param secs New max age. `wrapLST` reverts when the oracle's `lastUpdated()`
    ///        is older than this.
    function setMaxOracleAge(uint256 secs) external onlyRole(GOV) {
        maxOracleAgeSecs = secs;
        emit MaxOracleAgeSet(secs);
    }

    function pause(uint16 fnId) external onlyRole(GUARDIAN) {
        _pause(fnId);
    }

    function unpause(uint16 fnId) external onlyRole(GOV) {
        _unpause(fnId);
    }

    // ── Views ────────────────────────────────────────────────────────────────

    function lstHeld() external view returns (uint256) {
        return _lstHeld;
    }
}

contracts/v2/modular-staking/modules/Val.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import {IStakingRouter} from "../interfaces/IStakingRouter.sol";
import {IStakingModule} from "../interfaces/IStakingModule.sol";
import {IDepositContract} from "../interfaces/IDepositContract.sol";
import {GranularPause} from "../../lib/GranularPause.sol";
import {Errors} from "../../lib/Errors.sol";

/// @title ValidatorModule - solo-validator staking module behind StakingRouter
/// @notice Refactor of `StakingCore`. The Router is now the sole MINTER on StToken,
///         so this module never touches share supply directly. Instead it:
///           1. Buffers ETH on `receiveDeposit()` (router-only entry).
///           2. Pushes 32-ETH chunks to the canonical beacon-chain deposit contract.
///           3. Forwards oracle-validated beacon balance reports to the Router so the
///              Router can rebase StToken.
///
/// Roles:
///   GOV          — config
///   ORACLE       — submit beacon balance reports (typically `OracleAdapter`)
///   GUARDIAN     — emergency pause
///   NODE_OPERATOR— call `depositToBeaconChain` with a validator's deposit data
contract ValidatorModule is AccessControl, ReentrancyGuard, GranularPause, IStakingModule {
    // ── Roles ─────────────────────────────────────────────────────────────────
    bytes32 public constant GOV = keccak256("GOV");
    bytes32 public constant ORACLE = keccak256("ORACLE");
    bytes32 public constant GUARDIAN = keccak256("GUARDIAN");
    bytes32 public constant NODE_OPERATOR = keccak256("NODE_OPERATOR");

    // ── Pause IDs ─────────────────────────────────────────────────────────────
    /// @notice Blocks `receiveDeposit`, `reportBeacon`, and `depositToBeaconChain`.
    uint16 public constant PAUSE_RECEIVE = 0;

    // ── Constants ─────────────────────────────────────────────────────────────
    /// @notice Default mainnet beacon-chain deposit contract address. Used when
    ///         the constructor receives `address(0)` for `beaconDepositContract`.
    address public constant DEFAULT_BEACON_DEPOSIT_CONTRACT = 0x00000000219ab540356cBB839Cbe05303d7705Fa;
    uint256 public constant DEPOSIT_AMOUNT = 32 ether;

    // ── Immutables ────────────────────────────────────────────────────────────
    IStakingRouter public immutable ROUTER;
    bytes32 public immutable MODULE_ID;
    /// @notice Configurable beacon-chain deposit contract. Defaults to the mainnet
    ///         address when constructor arg is `address(0)`. Holesky/Hoodi and
    ///         hardhat tests pass alternative addresses.
    address public immutable BEACON_DEPOSIT_CONTRACT;

    // ── State ─────────────────────────────────────────────────────────────────
    uint256 internal _bufferedEther;     // ETH held here, pending validator assignment
    uint256 internal _beaconBalance;     // last reported sum of validator balances
    uint256 internal _beaconValidators;  // last reported validator count
    bytes32 public expectedWithdrawalCredentials; // validated withdrawal creds prefix

    // ── Events ────────────────────────────────────────────────────────────────
    event DepositReceived(uint256 amount, uint256 newBufferedEther);
    event BeaconReported(uint256 beaconValidators, uint256 beaconBalance);
    event BeaconChainDeposit(bytes pubkey, uint256 amount, uint256 newBufferedEther);
    event ExpectedWithdrawalCredentialsSet(bytes32 indexed expected);

    // ── Errors ────────────────────────────────────────────────────────────────
    error NotRouter(address caller);
    error InsufficientBuffer(uint256 available, uint256 required);
    error BeaconBalanceSanityFailed(uint256 reported, uint256 expected);
    error InvalidWithdrawalCredentials();

    constructor(address router, bytes32 moduleId, address gov, address beaconDepositContract) {
        if (router == address(0) || gov == address(0)) revert Errors.ZeroAddress();
        if (moduleId == bytes32(0)) revert Errors.InvalidAmount();
        ROUTER = IStakingRouter(router);
        MODULE_ID = moduleId;
        BEACON_DEPOSIT_CONTRACT = beaconDepositContract == address(0)
            ? DEFAULT_BEACON_DEPOSIT_CONTRACT
            : beaconDepositContract;

        _grantRole(DEFAULT_ADMIN_ROLE, gov);
        _grantRole(GOV, gov);
        _grantRole(GUARDIAN, gov);
    }

    // ── Module hooks (router-only) ───────────────────────────────────────────

    modifier onlyRouter() {
        if (msg.sender != address(ROUTER)) revert NotRouter(msg.sender);
        _;
    }

    /// @inheritdoc IStakingModule
    function receiveDeposit() external payable virtual override onlyRouter whenNotPaused(PAUSE_RECEIVE) {
        _bufferedEther += msg.value;
        emit DepositReceived(msg.value, _bufferedEther);
    }

    /// @inheritdoc IStakingModule
    function totalEth() external view virtual override returns (uint256) {
        return _bufferedEther + _beaconBalance;
    }

    /// @inheritdoc IStakingModule
    function moduleType() external pure virtual override returns (bytes32) {
        return keccak256("SOLO_VALIDATOR");
    }

    // ── Oracle reporting ─────────────────────────────────────────────────────

    /// @notice ORACLE forwards a (already sanity-checked at adapter) report. We add
    ///         a defensive cap here too in case the adapter is misconfigured.
    function reportBeacon(uint256 newBeaconValidators, uint256 newBeaconBalance)
        external
        onlyRole(ORACLE)
        whenNotPaused(PAUSE_RECEIVE)
    {
        if (_beaconValidators > 0) {
            uint256 maxPlausible = _beaconValidators * 32 ether * 3 / 2;
            if (newBeaconBalance > maxPlausible) {
                revert BeaconBalanceSanityFailed(newBeaconBalance, maxPlausible);
            }
        }

        _beaconValidators = newBeaconValidators;
        _beaconBalance = newBeaconBalance;

        ROUTER.reportModuleBeaconBalance(MODULE_ID, newBeaconBalance);
        emit BeaconReported(newBeaconValidators, newBeaconBalance);
    }

    // ── Beacon-chain deposit (NODE_OPERATOR) ─────────────────────────────────

    /// @notice Push exactly 32 ETH from the buffer into the canonical beacon deposit
    ///         contract using the supplied validator credentials. Notifies the Router
    ///         so its `moduleBeaconBalance` baseline tracks the principal.
    function depositToBeaconChain(
        bytes calldata pubkey,
        bytes calldata withdrawal_credentials,
        bytes calldata signature,
        bytes32 deposit_data_root
    ) external onlyRole(NODE_OPERATOR) nonReentrant whenNotPaused(PAUSE_RECEIVE) {
        if (_bufferedEther < DEPOSIT_AMOUNT) {
            revert InsufficientBuffer(_bufferedEther, DEPOSIT_AMOUNT);
        }

        // Validate withdrawal credentials belong to the protocol
        bytes32 expected = expectedWithdrawalCredentials;
        if (expected != bytes32(0)) {
            if (withdrawal_credentials.length != 32) revert InvalidWithdrawalCredentials();
            bytes32 provided;
            assembly {
                provided := calldataload(add(withdrawal_credentials.offset, 0))
            }
            if (provided != expected) revert InvalidWithdrawalCredentials();
        }

        _bufferedEther -= DEPOSIT_AMOUNT;

        IDepositContract(BEACON_DEPOSIT_CONTRACT).deposit{value: DEPOSIT_AMOUNT}(
            pubkey,
            withdrawal_credentials,
            signature,
            deposit_data_root
        );

        // Bump the router's baseline so subsequent oracle reports treat 32 ETH as
        // already "in the beacon" (no double-count vs. existing totalPooledEther).
        ROUTER.notifyBeaconDeposit(MODULE_ID, DEPOSIT_AMOUNT);

        emit BeaconChainDeposit(pubkey, DEPOSIT_AMOUNT, _bufferedEther);
    }

    // ── Admin ────────────────────────────────────────────────────────────────

    function setExpectedWithdrawalCredentials(bytes32 _expected) external onlyRole(GOV) {
        expectedWithdrawalCredentials = _expected;
        emit ExpectedWithdrawalCredentialsSet(_expected);
    }

    // ── Pause ────────────────────────────────────────────────────────────────

    function pause(uint16 fnId) external onlyRole(GUARDIAN) {
        _pause(fnId);
    }

    function unpause(uint16 fnId) external onlyRole(GOV) {
        _unpause(fnId);
    }

    // ── Views ────────────────────────────────────────────────────────────────

    function bufferedEther() external view returns (uint256) {
        return _bufferedEther;
    }

    function beaconBalance() external view returns (uint256) {
        return _beaconBalance;
    }

    function beaconValidators() external view returns (uint256) {
        return _beaconValidators;
    }

    /// @dev Direct ETH transfers are accepted but do NOT update _bufferedEther.
    ///      Only Router-mediated deposits via receiveDeposit() update accounting.
    ///      This prevents unbacked ETH from inflating totalEth() and breaking the
    ///      Router accounting invariant (totalPooledEther == sum module.totalEth()).
    receive() external payable virtual {
        emit DepositReceived(msg.value, _bufferedEther);
    }
}

contracts/v2/modular-staking/OracleAdapt.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {IReportable} from "./interfaces/IReportable.sol";
import {Errors} from "../lib/Errors.sol";

/// @title OracleAdapter - beacon chain report ingestion with sanity gates
/// @notice Accepts signed reports from authorized submitters and forwards valid
///         ones to a target implementing IReportable. The target can be either
///         the legacy `StakingCore` or a `ValidatorModule` behind StakingRouter
///         — both expose `reportBeacon(uint256,uint256)` with identical semantics.
///
/// Safety rules enforced before forwarding:
///   1. Staleness   — report must arrive within `maxStalenessSeconds` of now.
///   2. Drift       — beacon balance change (per validator) must not exceed `maxDriftBps` bps.
///   3. Slash guard — balance cannot drop more than `maxSlashBps` bps per report.
///
/// @dev Multiple submitters are supported so oracle infra can be redundant.
///      A quorum mechanism (requiring M-of-N) is intentionally deferred to Phase 2.
contract OracleAdapter is AccessControl {
    // ── Roles ─────────────────────────────────────────────────────────────────
    bytes32 public constant GOV = keccak256("GOV");
    bytes32 public constant SUBMITTER = keccak256("SUBMITTER");

    // ── Config ────────────────────────────────────────────────────────────────
    IReportable public immutable REPORT_TARGET;

    uint256 public maxStalenessSeconds = 6 hours;
    uint256 public maxDriftBps = 1000;  // 10% per-validator balance change cap
    uint256 public maxSlashBps = 500;   // 5% total-balance slash cap per report

    // ── State ─────────────────────────────────────────────────────────────────
    uint256 public lastReportTime;
    uint256 public lastBeaconBalance;
    uint256 public lastBeaconValidators;

    // ── Events ────────────────────────────────────────────────────────────────
    event ReportSubmitted(
        address indexed submitter,
        uint256 beaconValidators,
        uint256 beaconBalance,
        uint256 timestamp
    );
    event ReportRejected(address indexed submitter, string reason);
    event MaxStalenessSet(uint256 seconds_);
    event MaxDriftSet(uint256 bps);
    event MaxSlashSet(uint256 bps);

    // ── Errors ────────────────────────────────────────────────────────────────
    error StaleReport(uint256 reportAge, uint256 maxAge);
    error BalanceDriftTooHigh(uint256 actual, uint256 max);
    error SlashTooLarge(uint256 actual, uint256 max);
    error FutureReportTimestamp(uint256 reportTimestamp, uint256 currentTimestamp);

    constructor(address reportTarget, address gov) {
        if (reportTarget == address(0) || gov == address(0)) revert Errors.ZeroAddress();
        REPORT_TARGET = IReportable(reportTarget);
        _grantRole(DEFAULT_ADMIN_ROLE, gov);
        _grantRole(GOV, gov);
    }

    // ── Report submission ─────────────────────────────────────────────────────

    /// @notice Submit a beacon chain report.
    ///         Reverts if any sanity check fails.
    /// @param beaconValidators  Number of active validators being reported.
    /// @param beaconBalance     Sum of validator balances in wei.
    /// @param reportTimestamp   Off-chain timestamp of the report (for staleness check).
    function submitReport(
        uint256 beaconValidators,
        uint256 beaconBalance,
        uint256 reportTimestamp
    ) external onlyRole(SUBMITTER) {
        // Reject reports from the future.
        if (reportTimestamp > block.timestamp) {
            revert FutureReportTimestamp(reportTimestamp, block.timestamp);
        }

        // 1. Staleness check.
        uint256 reportAge = block.timestamp > reportTimestamp ? block.timestamp - reportTimestamp : 0;
        if (reportAge > maxStalenessSeconds) {
            revert StaleReport(reportAge, maxStalenessSeconds);
        }

        // 2. Drift check: per-validator balance change must be within bounds.
        if (lastBeaconValidators > 0 && beaconValidators > 0) {
            uint256 prevAvg = lastBeaconBalance / lastBeaconValidators;
            uint256 newAvg = beaconBalance / beaconValidators;

            if (newAvg > prevAvg) {
                uint256 gainBps = ((newAvg - prevAvg) * 10000) / prevAvg;
                if (gainBps > maxDriftBps) revert BalanceDriftTooHigh(gainBps, maxDriftBps);
            }
        }

        // 3. Slash guard: total balance cannot fall by more than maxSlashBps.
        if (lastBeaconBalance > 0 && beaconBalance < lastBeaconBalance) {
            uint256 lossBps = ((lastBeaconBalance - beaconBalance) * 10000) / lastBeaconBalance;
            if (lossBps > maxSlashBps) revert SlashTooLarge(lossBps, maxSlashBps);
        }

        // All checks pass — update state and forward to StakingCore.
        lastBeaconBalance = beaconBalance;
        lastBeaconValidators = beaconValidators;
        lastReportTime = block.timestamp;

        REPORT_TARGET.reportBeacon(beaconValidators, beaconBalance);

        emit ReportSubmitted(msg.sender, beaconValidators, beaconBalance, reportTimestamp);
    }

    // ── Config (GOV only) ─────────────────────────────────────────────────────

    function setMaxStaleness(uint256 seconds_) external onlyRole(GOV) {
        maxStalenessSeconds = seconds_;
        emit MaxStalenessSet(seconds_);
    }

    function setMaxDriftBps(uint256 bps) external onlyRole(GOV) {
        maxDriftBps = bps;
        emit MaxDriftSet(bps);
    }

    function setMaxSlashBps(uint256 bps) external onlyRole(GOV) {
        maxSlashBps = bps;
        emit MaxSlashSet(bps);
    }

    function addSubmitter(address submitter) external onlyRole(GOV) {
        if (submitter == address(0)) revert Errors.ZeroAddress();
        grantRole(SUBMITTER, submitter);
    }

    function removeSubmitter(address submitter) external onlyRole(GOV) {
        revokeRole(SUBMITTER, submitter);
    }
}

