// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {IReportable} from "./interfaces/IReportable.sol";
import {Errors} from "../lib/Errors.sol";

/// @title QuorumOracleAdapter - threshold-consensus beacon report adapter
/// @notice Accepts report votes from authorized submitters and forwards the
///         report to an IReportable target once quorum is reached and sanity
///         checks pass.
contract QuorumOracleAdapter is AccessControl {
    // ── Roles ─────────────────────────────────────────────────────────────────
    bytes32 public constant GOV = keccak256("GOV");
    bytes32 public constant SUBMITTER = keccak256("SUBMITTER");

    // ── Config ────────────────────────────────────────────────────────────────
    IReportable public immutable REPORT_TARGET;
    uint256 public quorum;
    uint256 public submitterCount;

    uint256 public maxStalenessSeconds = 6 hours;
    uint256 public maxDriftBps = 1000; // 10% per-validator balance change cap
    uint256 public maxSlashBps = 500; // 5% total-balance slash cap per report

    // ── State ─────────────────────────────────────────────────────────────────
    uint256 public lastReportTime;
    uint256 public lastBeaconBalance;
    uint256 public lastBeaconValidators;

    mapping(bytes32 => uint256) public reportVotes;
    mapping(bytes32 => bool) public reportFinalized;
    mapping(bytes32 => mapping(address => bool)) public hasVoted;

    // ── Events ────────────────────────────────────────────────────────────────
    event VoteSubmitted(
        bytes32 indexed reportHash,
        address indexed submitter,
        uint256 beaconValidators,
        uint256 beaconBalance,
        uint256 reportTimestamp,
        uint256 votes,
        uint256 quorum
    );
    event ReportFinalized(
        bytes32 indexed reportHash,
        uint256 beaconValidators,
        uint256 beaconBalance,
        uint256 reportTimestamp,
        uint256 votes
    );
    event SubmitterAdded(address indexed submitter);
    event SubmitterRemoved(address indexed submitter);
    event QuorumSet(uint256 quorum);
    event MaxStalenessSet(uint256 seconds_);
    event MaxDriftSet(uint256 bps);
    event MaxSlashSet(uint256 bps);

    // ── Errors ────────────────────────────────────────────────────────────────
    error InvalidQuorum(uint256 provided, uint256 submitterCount_);
    error DuplicateVote(bytes32 reportHash, address submitter);
    error ReportAlreadyFinalized(bytes32 reportHash);
    error StaleReport(uint256 reportAge, uint256 maxAge);
    error FutureReportTimestamp(uint256 reportTimestamp, uint256 currentTimestamp);
    error BalanceDriftTooHigh(uint256 actual, uint256 max);
    error SlashTooLarge(uint256 actual, uint256 max);

    constructor(address reportTarget, address gov, uint256 initialQuorum) {
        if (reportTarget == address(0) || gov == address(0)) revert Errors.ZeroAddress();
        if (initialQuorum == 0) revert InvalidQuorum(initialQuorum, 0);

        REPORT_TARGET = IReportable(reportTarget);
        quorum = initialQuorum;

        _grantRole(DEFAULT_ADMIN_ROLE, gov);
        _grantRole(GOV, gov);
    }

    // ── Report voting / finalization ─────────────────────────────────────────

    /// @notice Submit a vote for a report payload.
    /// @dev A payload is uniquely identified by (beaconValidators, beaconBalance, reportTimestamp).
    ///      The same submitter cannot vote twice for the same payload.
    function submitReport(
        uint256 beaconValidators,
        uint256 beaconBalance,
        uint256 reportTimestamp
    ) external onlyRole(SUBMITTER) {
        bytes32 reportHash = keccak256(abi.encode(beaconValidators, beaconBalance, reportTimestamp));

        if (reportFinalized[reportHash]) revert ReportAlreadyFinalized(reportHash);
        if (hasVoted[reportHash][msg.sender]) revert DuplicateVote(reportHash, msg.sender);

        hasVoted[reportHash][msg.sender] = true;
        uint256 votes = ++reportVotes[reportHash];

        emit VoteSubmitted(
            reportHash,
            msg.sender,
            beaconValidators,
            beaconBalance,
            reportTimestamp,
            votes,
            quorum
        );

        if (votes < quorum) return;

        _enforceSanityChecks(beaconValidators, beaconBalance, reportTimestamp);

        reportFinalized[reportHash] = true;
        lastBeaconBalance = beaconBalance;
        lastBeaconValidators = beaconValidators;
        lastReportTime = block.timestamp;

        REPORT_TARGET.reportBeacon(beaconValidators, beaconBalance);

        emit ReportFinalized(reportHash, beaconValidators, beaconBalance, reportTimestamp, votes);
    }

    function _enforceSanityChecks(
        uint256 beaconValidators,
        uint256 beaconBalance,
        uint256 reportTimestamp
    ) internal view {
        if (reportTimestamp > block.timestamp) {
            revert FutureReportTimestamp(reportTimestamp, block.timestamp);
        }

        uint256 reportAge = block.timestamp - reportTimestamp;
        if (reportAge > maxStalenessSeconds) {
            revert StaleReport(reportAge, maxStalenessSeconds);
        }

        if (lastBeaconValidators > 0 && beaconValidators > 0) {
            uint256 prevAvg = lastBeaconBalance / lastBeaconValidators;
            uint256 newAvg = beaconBalance / beaconValidators;

            if (prevAvg > 0 && newAvg > prevAvg) {
                uint256 gainBps = ((newAvg - prevAvg) * 10000) / prevAvg;
                if (gainBps > maxDriftBps) revert BalanceDriftTooHigh(gainBps, maxDriftBps);
            }
        }

        if (lastBeaconBalance > 0 && beaconBalance < lastBeaconBalance) {
            uint256 lossBps = ((lastBeaconBalance - beaconBalance) * 10000) / lastBeaconBalance;
            if (lossBps > maxSlashBps) revert SlashTooLarge(lossBps, maxSlashBps);
        }
    }

    // ── Config (GOV only) ─────────────────────────────────────────────────────

    function setQuorum(uint256 newQuorum) external onlyRole(GOV) {
        if (newQuorum == 0 || newQuorum > submitterCount) {
            revert InvalidQuorum(newQuorum, submitterCount);
        }
        quorum = newQuorum;
        emit QuorumSet(newQuorum);
    }

    function setMaxStaleness(uint256 seconds_) external onlyRole(GOV) {
        maxStalenessSeconds = seconds_;
        emit MaxStalenessSet(seconds_);
    }

    function setMaxDriftBps(uint256 bps) external onlyRole(GOV) {
        maxDriftBps = bps;
        emit MaxDriftSet(bps);
    }

    function setMaxSlashBps(uint256 bps) external onlyRole(GOV) {
        maxSlashBps = bps;
        emit MaxSlashSet(bps);
    }

    function addSubmitter(address submitter) external onlyRole(GOV) {
        if (submitter == address(0)) revert Errors.ZeroAddress();
        if (!hasRole(SUBMITTER, submitter)) {
            grantRole(SUBMITTER, submitter);
            submitterCount += 1;
            emit SubmitterAdded(submitter);
        }
    }

    function removeSubmitter(address submitter) external onlyRole(GOV) {
        if (!hasRole(SUBMITTER, submitter)) return;

        uint256 newCount = submitterCount - 1;
        if (quorum > newCount) revert InvalidQuorum(quorum, newCount);

        revokeRole(SUBMITTER, submitter);
        submitterCount = newCount;
        emit SubmitterRemoved(submitter);
    }
}

contracts/v2/modular-staking/ReferralReg.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Errors} from "../lib/Errors.sol";

/// @title ReferralRegistry — on-chain referral attribution for SharedStake V2
/// @notice Tracks referrer → referee relationships and accrued referral fees.
///         Uses a MasterChef-style reward-per-share model for gas-efficient
///         fee distribution across all referrers.
///
///         Integration:
///           - StakingRouter calls `recordDeposit(referee, referrer, ethAmount, shares)`
///             on every deposit that includes a referral address.
///           - StakingRouter mints fee shares to this contract and calls
///             `depositReferralFeeShares(shares)`.
///           - Referrers claim accrued fee shares proportional to their referred volume.
///
///         Anti-gaming:
///           - Self-referral is blocked (referee == referrer).
///           - Referrer must have referred at least `minReferralStake` total ETH
///             before they can claim fees.
///           - GOV can adjust fee rate and minimums.
///
/// Roles:
///   GOV        — set fee params, recover stranded tokens
///   FEE_CTRL   — deposit fee revenue (StakingRouter via FeeController role)
///   ROUTER     — record deposits (StakingRouter)
contract ReferralRegistry is AccessControl, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ── Roles ─────────────────────────────────────────────────────────────────
    bytes32 public constant GOV = keccak256("GOV");
    bytes32 public constant FEE_CTRL = keccak256("FEE_CTRL");
    bytes32 public constant ROUTER = keccak256("ROUTER");

    // ── State ───────────────────────────────────────────────────────────────────
    struct ReferralRecord {
        uint256 totalReferredEth;      // cumulative ETH deposited by referee
        uint256 totalReferredShares;   // cumulative shares minted to referee
        uint256 firstReferralTime;     // timestamp of first referral
    }

    struct ReferrerStats {
        uint256 totalReferredEth;      // cumulative across all referees
        uint256 totalReferredShares;   // cumulative across all referees
        uint256 refereeCount;          // number of unique referees
        int256 rewardDebt;             // MasterChef-style reward debt
    }

    /// @notice referralFeeBps: percentage of protocol fees directed to referrals
    ///         e.g., 1000 = 10% of protocol fees go to referral pool.
    uint256 public referralFeeBps = 1000; // 10% default
    uint256 public constant MAX_REFERRAL_FEE_BPS = 3000; // 30% cap
    uint256 public minReferralStake = 1 ether; // must have referred ≥1 ETH to claim

    /// @notice MasterChef-style accrual: accumulated fee shares per unit of referred ETH.
    uint256 public accRewardPerEth;
    uint256 public constant ACC_PRECISION = 1e18;
    uint256 public totalReferredEth; // cumulative ETH referred across ALL referrers

    mapping(address => mapping(address => ReferralRecord)) public records; // referrer => referee => record
    mapping(address => ReferrerStats) public stats;
    mapping(address => bool) public hasReferred; // referee => true (prevents re-referral)

    address public feeToken; // token used for fee payouts (address(0) = stToken shares)

    // ── Events ────────────────────────────────────────────────────────────────
    event DepositRecorded(address indexed referrer, address indexed referee, uint256 ethAmount, uint256 shares);
    event FeeSharesDeposited(address indexed sender, uint256 shares);
    event FeesClaimed(address indexed referrer, uint256 shares);
    event ReferralFeeBpsSet(uint256 oldBps, uint256 newBps);
    event MinReferralStakeSet(uint256 oldMin, uint256 newMin);

    // ── Errors ────────────────────────────────────────────────────────────────
    error SelfReferral();
    error ZeroAmount();
    error MinStakeNotMet(uint256 required, uint256 actual);
    error NoFeesToClaim();
    error FeeTooHigh();
    error NoReferees();

    constructor(address _gov, address _feeToken) {
        if (_gov == address(0)) revert Errors.ZeroAddress();
        if (_feeToken == address(0)) revert Errors.ZeroAddress();
        _grantRole(DEFAULT_ADMIN_ROLE, _gov);
        _grantRole(GOV, _gov);
        feeToken = _feeToken;
    }

    // ── Core: deposit recording (ROUTER only) ───────────────────────────────

    /// @notice Called by StakingRouter on each deposit with a referral address.
    ///         Records the referrer → referee relationship and referred amounts.
    function recordDeposit(
        address referrer,
        address referee,
        uint256 ethAmount,
        uint256 shares
    ) external onlyRole(ROUTER) {
        if (referrer == address(0)) return; // no-op for missing referral
        if (referrer == referee) revert SelfReferral();
        if (ethAmount == 0 || shares == 0) revert ZeroAmount();

        // Prevent a referee from being referred twice (first referrer wins)
        if (hasReferred[referee]) {
            return;
        }
        hasReferred[referee] = true;

        ReferralRecord storage rec = records[referrer][referee];
        rec.totalReferredEth += ethAmount;
        rec.totalReferredShares += shares;
        if (rec.firstReferralTime == 0) {
            rec.firstReferralTime = block.timestamp;
        }

        ReferrerStats storage s = stats[referrer];
        // Update reward debt before changing totalReferredEth
        s.rewardDebt += int256((ethAmount * accRewardPerEth) / ACC_PRECISION);
        s.totalReferredEth += ethAmount;
        s.totalReferredShares += shares;
        s.refereeCount += 1;

        totalReferredEth += ethAmount;

        emit DepositRecorded(referrer, referee, ethAmount, shares);
    }

    // ── Core: fee deposit (FEE_CTRL only) ─────────────────────────────────────

    /// @notice Called by StakingRouter when fee shares are minted to this contract.
    ///         Distributes new shares proportionally across all referrers via
    ///         the accRewardPerEth accumulator.
    function depositReferralFeeShares(uint256 shares) external onlyRole(FEE_CTRL) {
        if (shares == 0) revert ZeroAmount();
        if (totalReferredEth == 0) revert NoReferees();

        accRewardPerEth += (shares * ACC_PRECISION) / totalReferredEth;
        emit FeeSharesDeposited(msg.sender, shares);
    }

    // ── Core: fee claiming ────────────────────────────────────────────────────

    /// @notice Referrer claims their accrued fee shares.
    function claimFees() external nonReentrant {
        ReferrerStats storage s = stats[msg.sender];
        uint256 referredEth = s.totalReferredEth;
        if (referredEth == 0) revert NoFeesToClaim();
        if (referredEth < minReferralStake) {
            revert MinStakeNotMet(minReferralStake, referredEth);
        }

        uint256 pending = _pendingReward(msg.sender);
        if (pending == 0) revert NoFeesToClaim();

        s.rewardDebt = int256((referredEth * accRewardPerEth) / ACC_PRECISION);

        // Transfer fee shares to referrer
        IERC20(feeToken).safeTransfer(msg.sender, pending);

        emit FeesClaimed(msg.sender, pending);
    }

    // ── Admin (GOV only) ────────────────────────────────────────────────────────

    function setReferralFeeBps(uint256 _bps) external onlyRole(GOV) {
        if (_bps > MAX_REFERRAL_FEE_BPS) revert FeeTooHigh();
        uint256 old = referralFeeBps;
        referralFeeBps = _bps;
        emit ReferralFeeBpsSet(old, _bps);
    }

    function setMinReferralStake(uint256 _min) external onlyRole(GOV) {
        uint256 old = minReferralStake;
        minReferralStake = _min;
        emit MinReferralStakeSet(old, _min);
    }

    function setFeeToken(address _token) external onlyRole(GOV) {
        feeToken = _token;
    }

    /// @notice Recover accidentally sent ERC20 tokens (not feeToken).
    function recoverToken(address token, address to, uint256 amount) external onlyRole(GOV) {
        if (token == feeToken) revert Errors.InvalidAmount();
        IERC20(token).safeTransfer(to, amount);
    }

    /// @notice Recover accidentally sent ETH.
    function recoverEth(address to, uint256 amount) external onlyRole(GOV) {
        (bool ok, ) = to.call{value: amount}("");
        require(ok, "ETH transfer failed");
    }

    // ── Views ─────────────────────────────────────────────────────────────────

    function getReferrerStats(address referrer)
        external
        view
        returns (ReferrerStats memory)
    {
        return stats[referrer];
    }

    function getRecord(address referrer, address referee)
        external
        view
        returns (ReferralRecord memory)
    {
        return records[referrer][referee];
    }

    function pendingReward(address referrer) external view returns (uint256) {
        return _pendingReward(referrer);
    }

    // ── Internal ──────────────────────────────────────────────────────────────

    function _pendingReward(address referrer) internal view returns (uint256) {
        ReferrerStats storage s = stats[referrer];
        uint256 referredEth = s.totalReferredEth;
        if (referredEth == 0) return 0;
        int256 accumulated = int256((referredEth * accRewardPerEth) / ACC_PRECISION);
        return uint256(accumulated - s.rewardDebt);
    }

    receive() external payable {}
}

contracts/v2/modular-staking/ShareMath.s.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

/// @title ShareMath - precision share accounting for the SharedStake V2 staking core
/// @notice All arithmetic uses 256-bit integers; Solidity 0.8 reverts on overflow.
///         Rounding policy: share minting rounds DOWN (protects pool);
///         pooled-ETH-by-shares rounds DOWN (protects pool on redemption).
library ShareMath {
    /// @dev Bootstrap: first depositor receives shares 1:1 with wei.
    ///      Prevents the classic "first deposit inflation" attack because the
    ///      attacker cannot make totalPooledEth >> totalShares before any shares exist.
    function getSharesByPooledEth(
        uint256 ethAmount,
        uint256 totalShares,
        uint256 totalPooledEth
    ) internal pure returns (uint256) {
        if (totalPooledEth == 0) {
            // Bootstrap: 1 wei => 1 share
            return ethAmount;
        }
        // Rounds DOWN: minter receives floor(shares). Pool balance never overstated.
        return (ethAmount * totalShares) / totalPooledEth;
    }

    function getPooledEthByShares(
        uint256 sharesAmount,
        uint256 totalShares,
        uint256 totalPooledEth
    ) internal pure returns (uint256) {
        if (totalShares == 0) {
            return 0;
        }
        // Rounds DOWN: redeemer receives floor(eth). Pool never drained beyond entitlement.
        return (sharesAmount * totalPooledEth) / totalShares;
    }

    /// @notice Exchange rate: how many wei one share is worth.
    ///         Returns 0 when no shares exist (undefined until first deposit).
    function sharePrice(uint256 totalShares, uint256 totalPooledEth) internal pure returns (uint256) {
        if (totalShares == 0) return 0;
        return (totalPooledEth * 1e18) / totalShares;
    }
}

contracts/v2/modular-staking/StakingCore.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import {StToken} from "./StToken.sol";
import {FeeController} from "./FeeController.sol";
import {ShareMath} from "./ShareMath.sol";
import {IReferralRegistry} from "./interfaces/IReferralRegistry.sol";
import {GranularPause} from "../lib/GranularPause.sol";
import {Errors} from "../lib/Errors.sol";

/// @title StakingCore - SharedStake V2 ETH staking vault
/// @notice Entry point for ETH deposits. Issues stToken shares to depositors.
///         Oracle (ORACLE role) reports beacon chain balance changes, triggering reward rebases.
///         Fee shares are minted to protocol recipients on each reward report.
///
/// Role model (principle of least privilege):
///   GOV          — governance (timelock/multisig): set fee controller, add/remove roles, unpause
///   ORACLE       — trusted report submitter (OracleAdapter contract)
///   GUARDIAN     — emergency pause (can act fast, no timelock needed)
///   NODE_OPERATOR— moves buffered ETH into beacon baseline via notifyBeaconDeposit
contract StakingCore is AccessControl, ReentrancyGuard, GranularPause {
    using ShareMath for *;

    // ── Roles ─────────────────────────────────────────────────────────────────
    bytes32 public constant GOV = keccak256("GOV");
    bytes32 public constant ORACLE = keccak256("ORACLE");
    bytes32 public constant GUARDIAN = keccak256("GUARDIAN");
    bytes32 public constant NODE_OPERATOR = keccak256("NODE_OPERATOR");

    // ── Pause IDs ─────────────────────────────────────────────────────────────
    uint16 public constant PAUSE_SUBMIT = 0;

    // ── Immutables ────────────────────────────────────────────────────────────
    StToken public immutable ST_TOKEN;

    // ── State ─────────────────────────────────────────────────────────────────
    FeeController public feeController;

    uint256 private _bufferedEther;   // ETH held in this contract (pending validator assignment)
    uint256 private _beaconBalance;   // last reported sum of all validator balances
    uint256 private _beaconValidators; // last reported validator count

    // ── Events ────────────────────────────────────────────────────────────────
    event Submitted(address indexed sender, uint256 ethAmount, address referral, uint256 sharesAmount);
    event SubmittedWithAttribution(
        address indexed sender,
        address indexed referral,
        bytes32 indexed sourceId,
        uint256 ethAmount,
        uint256 sharesAmount
    );
    event BeaconReported(uint256 beaconValidators, uint256 beaconBalance, uint256 totalPooledEther);
    event FeeSharesMinted(address indexed treasury, uint256 treasuryShares, address indexed operator, uint256 operatorShares);
    event FeeRoutingTelemetry(
        uint256 rewardsAmount,
        uint256 totalFeeAmount,
        address indexed treasury,
        uint256 treasuryAmount,
        uint256 treasuryShares,
        address indexed operator,
        uint256 operatorAmount,
        uint256 operatorShares
    );
    event FeeControllerSet(address indexed feeController);
    event BufferedEtherUpdated(uint256 bufferedEther);
    event BeaconDepositNotified(uint256 amount, uint256 bufferedEther, uint256 beaconBalance);

    // ── Errors ────────────────────────────────────────────────────────────────
    error BeaconBalanceSanityFailed(uint256 reported, uint256 expected);
    error BeaconBaselineNotInitialized(uint256 reportedBalance);
    error BeaconDepositExceedsBuffered(uint256 amount, uint256 bufferedEther);

    constructor(address stToken, address gov) {
        if (stToken == address(0) || gov == address(0)) revert Errors.ZeroAddress();
        ST_TOKEN = StToken(stToken);
        _grantRole(DEFAULT_ADMIN_ROLE, gov);
        _grantRole(GOV, gov);
        _grantRole(GUARDIAN, gov);
        _grantRole(NODE_OPERATOR, gov);
    }

    // ── Deposit ───────────────────────────────────────────────────────────────

    /// @notice Deposit ETH and receive stToken shares.
    /// @param referral Optional referral address for front-end attribution.
    /// @return sharesAmount Shares minted to msg.sender.
    function submit(address referral)
        external
        payable
        nonReentrant
        whenNotPaused(PAUSE_SUBMIT)
        returns (uint256 sharesAmount)
    {
        if (msg.value == 0) revert Errors.InvalidAmount();
        sharesAmount = _submit(msg.sender, msg.value, referral);
    }

    /// @notice Deposit ETH and receive stToken shares with source attribution metadata.
    /// @param referral Optional referral address for front-end attribution.
    /// @param sourceId Optional source identifier for indexer and analytics attribution.
    /// @return sharesAmount Shares minted to msg.sender.
    function submitWithAttribution(address referral, bytes32 sourceId)
        external
        payable
        nonReentrant
        whenNotPaused(PAUSE_SUBMIT)
        returns (uint256 sharesAmount)
    {
        if (msg.value == 0) revert Errors.InvalidAmount();
        sharesAmount = _submit(msg.sender, msg.value, referral);
        emit SubmittedWithAttribution(msg.sender, referral, sourceId, msg.value, sharesAmount);
    }

    /// @notice Fallback: plain ETH transfer treated as a deposit with no referral.
    receive() external payable nonReentrant whenNotPaused(PAUSE_SUBMIT) {
        if (msg.value == 0) revert Errors.InvalidAmount();
        _submit(msg.sender, msg.value, address(0));
    }

    function _submit(address sender, uint256 amount, address referral) internal returns (uint256 sharesAmount) {
        uint256 currentPooled = ST_TOKEN.totalPooledEther();
        uint256 currentShares = ST_TOKEN.getTotalShares();

        sharesAmount = ShareMath.getSharesByPooledEth(amount, currentShares, currentPooled);

        _bufferedEther += amount;
        // Pool grows by deposit amount before shares are issued (conservative: no dilution).
        ST_TOKEN.setTotalPooledEther(currentPooled + amount);
        ST_TOKEN.mintShares(sender, sharesAmount);
        _recordReferral(sender, referral, amount, sharesAmount);

        emit Submitted(sender, amount, referral, sharesAmount);
        emit BufferedEtherUpdated(_bufferedEther);
    }

    // ── Oracle reporting ──────────────────────────────────────────────────────

    /// @notice Called by OracleAdapter when a new beacon chain report is accepted.
    ///         Updates totalPooledEther and distributes fee shares on positive rewards.
    /// @param newBeaconValidators Number of validators being reported.
    /// @param newBeaconBalance    Sum of all validator balances (in wei).
    function reportBeacon(uint256 newBeaconValidators, uint256 newBeaconBalance)
        external
        onlyRole(ORACLE)
    {
        // Sanity: beacon balance cannot be more than 1.5× the maximum honest value.
        if (newBeaconValidators > 0) {
            uint256 maxPlausible = newBeaconValidators * 32 ether * 3 / 2;
            if (newBeaconBalance > maxPlausible) {
                revert BeaconBalanceSanityFailed(newBeaconBalance, maxPlausible);
            }
        }

        // Prevent principal from being counted as rewards on the first positive
        // report. NODE_OPERATOR must move buffered ETH into beacon baseline first.
        if (_beaconBalance == 0 && newBeaconBalance > 0) {
            revert BeaconBaselineNotInitialized(newBeaconBalance);
        }

        uint256 preTotalPooled = ST_TOKEN.totalPooledEther();

        _beaconValidators = newBeaconValidators;
        _beaconBalance = newBeaconBalance;

        uint256 postTotalPooled = _bufferedEther + newBeaconBalance;
        ST_TOKEN.setTotalPooledEther(postTotalPooled);

        // Distribute fee shares when there are positive rewards.
        if (postTotalPooled > preTotalPooled && address(feeController) != address(0)) {
            uint256 rewards = postTotalPooled - preTotalPooled;
            _distributeFees(rewards, postTotalPooled);
        }

        emit BeaconReported(newBeaconValidators, newBeaconBalance, postTotalPooled);
    }

    /// @notice Moves ETH accounting from buffered to beacon-side baseline.
    /// @dev Called by NODE_OPERATOR when validator deposits are broadcast.
    ///      Keeps total pooled ETH unchanged while initializing or growing the
    ///      beacon baseline used by oracle delta reports.
    function notifyBeaconDeposit(uint256 amount) external onlyRole(NODE_OPERATOR) {
        if (amount == 0) revert Errors.InvalidAmount();
        uint256 buffered = _bufferedEther;
        if (amount > buffered) revert BeaconDepositExceedsBuffered(amount, buffered);

        _bufferedEther = buffered - amount;
        _beaconBalance += amount;

        emit BeaconDepositNotified(amount, _bufferedEther, _beaconBalance);
        emit BufferedEtherUpdated(_bufferedEther);
    }

    function _distributeFees(uint256 rewards, uint256 newTotalPooled) internal {
        (, , , address treasury, address operator, address referralRegistry) = feeController.getFeeConfig();

        (uint256 treasuryAmount, uint256 operatorAmount, uint256 referralAmount) = feeController.computeFees(rewards);
        if (referralRegistry == address(0)) {
            referralAmount = 0;
        }
        if (treasuryAmount == 0 && operatorAmount == 0 && referralAmount == 0) return;

        uint256 totalFee = treasuryAmount + operatorAmount + referralAmount;
        uint256 newTotalShares = ST_TOKEN.getTotalShares();

        // Mint fee shares at the post-rebase exchange rate so fee recipients are
        // compensated exactly for their portion of the rewards.
        uint256 treasuryShares = ShareMath.getSharesByPooledEth(treasuryAmount, newTotalShares, newTotalPooled);
        uint256 operatorShares = ShareMath.getSharesByPooledEth(operatorAmount, newTotalShares, newTotalPooled);
        uint256 referralShares = ShareMath.getSharesByPooledEth(referralAmount, newTotalShares, newTotalPooled);

        // Keep pool accounting strictly tied to real backing (buffer + beacon).
        // Fee recipients are paid via share dilution from existing rewards.

        if (treasuryShares > 0) ST_TOKEN.mintShares(treasury, treasuryShares);
        if (operatorShares > 0) ST_TOKEN.mintShares(operator, operatorShares);
        if (referralRegistry != address(0) && referralShares > 0) {
            ST_TOKEN.mintShares(referralRegistry, referralShares);
            IReferralRegistry(referralRegistry).depositReferralFeeShares(referralShares);
        }

        emit FeeSharesMinted(treasury, treasuryShares, operator, operatorShares);
        emit FeeRoutingTelemetry(
            rewards,
            totalFee,
            treasury,
            treasuryAmount,
            treasuryShares,
            operator,
            operatorAmount,
            operatorShares
        );
    }

    function _recordReferral(address sender, address referral, uint256 amount, uint256 sharesAmount) internal {
        if (referral == address(0) || address(feeController) == address(0)) return;
        (, , , , , address referralRegistry) = feeController.getFeeConfig();
        if (referralRegistry == address(0)) return;
        IReferralRegistry(referralRegistry).recordDeposit(referral, sender, amount, sharesAmount);
    }

    // ── Admin ─────────────────────────────────────────────────────────────────

    function setFeeController(address fc) external onlyRole(GOV) {
        if (fc == address(0)) revert Errors.ZeroAddress();
        feeController = FeeController(fc);
        emit FeeControllerSet(fc);
    }

    function pause(uint16 fnId) external onlyRole(GUARDIAN) {
        _pause(fnId);
    }

    function unpause(uint16 fnId) external onlyRole(GOV) {
        _unpause(fnId);
    }

    // ── Views ─────────────────────────────────────────────────────────────────

    function totalPooledEther() external view returns (uint256) {
        return _bufferedEther + _beaconBalance;
    }

    function bufferedEther() external view returns (uint256) {
        return _bufferedEther;
    }

    function beaconBalance() external view returns (uint256) {
        return _beaconBalance;
    }

    function beaconValidators() external view returns (uint256) {
        return _beaconValidators;
    }
}

contracts/v2/modular-staking/StakingRout.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import {StToken} from "./StToken.sol";
import {FeeController} from "./FeeController.sol";
import {ShareMath} from "./ShareMath.sol";
import {IStakingModule} from "./interfaces/IStakingModule.sol";
import {IStakingRouter} from "./interfaces/IStakingRouter.sol";
import {IInstitutionalPolicyRegistry} from "./interfaces/IInstitutionalPolicyRegistry.sol";
import {IReferralRegistry} from "./interfaces/IReferralRegistry.sol";
import {GranularPause} from "../lib/GranularPause.sol";
import {Errors} from "../lib/Errors.sol";

/// @title StakingRouter - modular front-door for ETH staking
/// @notice The Router is the single MINTER on StToken for deposits and rebases.
///         It maintains a registry of modules, each with its own ETH custody and
///         (optionally) validator orchestration. Deposits are routed to a default
///         module or to a caller-specified module. Per-module mint caps prevent
///         any single module from breaching its risk budget.
///
/// Accounting invariant:
///         totalPooledEther == sum_over_modules( module.totalEth() )
///                          == sum( bufferedEther_i + beaconBalance_i ) for validator modules
///                          == priceOracle.getEthValue(lstHeld_i) for LST modules
///
///         The Router stores `moduleBeaconBalance[moduleId]` — the baseline of the
///         module's beacon side. It is bumped when validator modules call
///         `notifyBeaconDeposit` (buffered-to-beacon transfer) and used as the
///         delta baseline when oracle reports arrive.
///
/// Role model:
///   GOV       — register/configure modules, set fee controller, unpause.
///   GUARDIAN  — emergency pause (no timelock).
contract StakingRouter is AccessControl, ReentrancyGuard, GranularPause, IStakingRouter {
    using ShareMath for *;

    struct FeeRoutingData {
        uint256 rewards;
        uint256 treasuryAmount;
        uint256 operatorAmount;
        uint256 treasuryShares;
        uint256 operatorShares;
        uint256 totalFeeAmount;
        uint256 totalPooledBeforeFees;
        uint256 totalPooledAfterFees;
    }

    struct InflowLimitConfig {
        uint256 windowSeconds;
        uint256 maxInflowEthPerWindow;
    }

    struct InflowWindowState {
        uint256 windowStart;
        uint256 inflowEth;
    }

    // ── Roles ─────────────────────────────────────────────────────────────────
    bytes32 public constant GOV = keccak256("GOV");
    bytes32 public constant GUARDIAN = keccak256("GUARDIAN");

    // ── Pause IDs ─────────────────────────────────────────────────────────────
    uint16 public constant PAUSE_SUBMIT = 0;

    // ── Immutables ────────────────────────────────────────────────────────────
    StToken public immutable ST_TOKEN;

    // ── State ─────────────────────────────────────────────────────────────────
    FeeController public feeController;

    /// @notice Module registry. moduleId => info.
    mapping(bytes32 => ModuleInfo) private _modules;

    /// @notice Last reported beacon balance per module — used for delta-only oracle reports.
    mapping(bytes32 => uint256) public moduleBeaconBalance;

    /// @notice Optional per-module limiter config. Disabled if either field is zero.
    mapping(bytes32 => InflowLimitConfig) public moduleInflowLimitConfig;

    /// @notice Current inflow window state per module.
    mapping(bytes32 => InflowWindowState) public moduleInflowWindowState;

    /// @notice The module that `submit()` (no moduleId) routes to.
    bytes32 public defaultModuleId;

    /// @notice Optional registry for institutional policy checks. Zero address disables checks.
    IInstitutionalPolicyRegistry public policyRegistry;

    /// @notice Optional per-module policy id. Zero value disables policy checks for that module.
    mapping(bytes32 => bytes32) public modulePolicyId;

    /// @notice Sanity bound (basis points) on per-report beacon balance gains.
    ///         A module reporting `newBeaconBalance > prior * (1 + maxDeltaBps/10000)`
    ///         reverts. Prevents a compromised/buggy module from inflating
    ///         `totalPooledEther` and diluting all stakers' shares.
    ///         Default 100 = 1% (safe for mainnet). Can be raised temporarily
    ///         via governance during high-reward periods (e.g. post-Merge).
    ///         Max absolute ceiling enforced at 1000 (10%) by setter.
    uint256 public maxDeltaBps = 100;

    /// @notice Global circuit breaker on total pooled ETH. Default 0 = unlimited.
    ///         When set to a non-zero value, any deposit or wrap that would push
    ///         totalPooledEther beyond this cap reverts. GOV can raise the cap
    ///         gradually as the protocol scales.
    uint256 public maxTotalPooledEther;

    // ── Events ────────────────────────────────────────────────────────────────
    event Deposited(
        bytes32 indexed moduleId,
        address indexed user,
        uint256 ethAmount,
        uint256 sharesAmount,
        address referral
    );
    event DepositAttributed(
        bytes32 indexed moduleId,
        address indexed user,
        bytes32 indexed sourceId,
        uint256 ethAmount,
        uint256 sharesAmount,
        address referral
    );
    event ModuleRegistered(bytes32 indexed moduleId, address indexed addr, bytes32 moduleType, uint256 mintCapEth);
    event ModuleMintCapSet(bytes32 indexed moduleId, uint256 mintCapEth);
    event ModulePausedSet(bytes32 indexed moduleId, bool paused);
    event DefaultModuleSet(bytes32 indexed moduleId);
    event ModuleBeaconReported(bytes32 indexed moduleId, uint256 newBeaconBalance, int256 delta);
    event BeaconDepositNotified(bytes32 indexed moduleId, uint256 amount);
    event FeeControllerSet(address indexed feeController);
    event FeeSharesMinted(address indexed treasury, uint256 treasuryShares, address indexed operator, uint256 operatorShares);
    event FeeRoutingTelemetry(
        bytes32 indexed moduleId,
        uint256 rewards,
        uint256 treasuryAmount,
        uint256 operatorAmount,
        uint256 treasuryShares,
        uint256 operatorShares,
        uint256 totalFeeAmount,
        uint256 totalPooledBeforeFees,
        uint256 totalPooledAfterFees
    );
    event LSTWrapped(bytes32 indexed moduleId, address indexed recipient, uint256 ethEquiv, uint256 sharesAmount);
    event LSTUnwrapped(bytes32 indexed moduleId, address indexed account, uint256 stTokenAmount, uint256 ethValue);
    event MaxDeltaBpsSet(uint256 newValue);
    event MaxTotalPooledEtherSet(uint256 newValue);
    event PoolInsolvent(bytes32 indexed moduleId, uint256 loss, uint256 pooledAtTime);
    event ModuleInflowLimitSet(bytes32 indexed moduleId, uint256 windowSeconds, uint256 maxInflowEthPerWindow);
    event PolicyRegistrySet(address indexed registry);
    event ModulePolicySet(bytes32 indexed moduleId, bytes32 indexed policyId);

    // ── Errors ────────────────────────────────────────────────────────────────
    error ModuleNotRegistered(bytes32 moduleId);
    error ModuleAlreadyRegistered(bytes32 moduleId);
    error ModuleInactive(bytes32 moduleId);
    error ModulePaused(bytes32 moduleId);
    error MintCapExceeded(bytes32 moduleId, uint256 attempted, uint256 cap);
    error NotModule(bytes32 moduleId, address caller);
    error DefaultModuleNotSet();
    error BeaconReportSanityFailed(bytes32 moduleId, uint256 gainBps, uint256 maxDeltaBps);
    error MaxTotalPooledExceeded(uint256 attempted, uint256 cap);
    error BeaconBaselineNotInitialized(bytes32 moduleId, uint256 reportedBalance);
    error InflowLimitExceeded(bytes32 moduleId, uint256 attemptedWindowInflow, uint256 maxInflowEthPerWindow);
    error PolicyDenied(bytes32 moduleId, bytes32 policyId, address account);

    constructor(address stToken, address gov) {
        if (stToken == address(0) || gov == address(0)) revert Errors.ZeroAddress();
        ST_TOKEN = StToken(stToken);
        _grantRole(DEFAULT_ADMIN_ROLE, gov);
        _grantRole(GOV, gov);
        _grantRole(GUARDIAN, gov);
    }

    // ── External: deposit entry points ────────────────────────────────────────

    /// @notice Deposit ETH and receive stToken shares from the default module.
    function submit(address referral)
        external
        payable
        nonReentrant
        whenNotPaused(PAUSE_SUBMIT)
        returns (uint256 sharesAmount)
    {
        if (msg.value == 0) revert Errors.InvalidAmount();
        if (defaultModuleId == bytes32(0)) revert DefaultModuleNotSet();
        sharesAmount = _deposit(defaultModuleId, msg.sender, msg.value, referral);
    }

    /// @notice Deposit ETH into a specific module by id.
    function submitToModule(bytes32 moduleId, address referral)
        external
        payable
        nonReentrant
        whenNotPaused(PAUSE_SUBMIT)
        returns (uint256 sharesAmount)
    {
        if (msg.value == 0) revert Errors.InvalidAmount();
        sharesAmount = _deposit(moduleId, msg.sender, msg.value, referral);
    }

    /// @notice Deposit ETH and include source attribution metadata for indexers.
    function submitWithSource(address referral, bytes32 sourceId)
        external
        payable
        nonReentrant
        whenNotPaused(PAUSE_SUBMIT)
        returns (uint256 sharesAmount)
    {
        if (msg.value == 0) revert Errors.InvalidAmount();
        if (defaultModuleId == bytes32(0)) revert DefaultModuleNotSet();
        sharesAmount = _depositWithAttribution(defaultModuleId, msg.sender, msg.value, referral, sourceId);
    }

    /// @notice Deposit ETH into a specific module and include source attribution metadata for indexers.
    function submitToModuleWithSource(bytes32 moduleId, address referral, bytes32 sourceId)
        external
        payable
        nonReentrant
        whenNotPaused(PAUSE_SUBMIT)
        returns (uint256 sharesAmount)
    {
        if (msg.value == 0) revert Errors.InvalidAmount();
        sharesAmount = _depositWithAttribution(moduleId, msg.sender, msg.value, referral, sourceId);
    }

    /// @dev Plain ETH transfer: route to default module (no referral).
    receive() external payable nonReentrant whenNotPaused(PAUSE_SUBMIT) {
        if (msg.value == 0) revert Errors.InvalidAmount();
        if (defaultModuleId == bytes32(0)) revert DefaultModuleNotSet();
        _deposit(defaultModuleId, msg.sender, msg.value, address(0));
    }

    // ── Internal: deposit pipeline ────────────────────────────────────────────

    function _deposit(bytes32 moduleId, address user, uint256 amount, address referral)
        internal
        returns (uint256 sharesAmount)
    {
        sharesAmount = _deposit(moduleId, user, amount, referral, false, bytes32(0));
    }

    function _depositWithAttribution(bytes32 moduleId, address user, uint256 amount, address referral, bytes32 sourceId)
        internal
        returns (uint256 sharesAmount)
    {
        sharesAmount = _deposit(moduleId, user, amount, referral, true, sourceId);
    }

    function _deposit(bytes32 moduleId, address user, uint256 amount, address referral, bool emitAttribution, bytes32 sourceId)
        internal
        returns (uint256 sharesAmount)
    {
        ModuleInfo storage m = _modules[moduleId];
        if (m.addr == address(0)) revert ModuleNotRegistered(moduleId);
        if (!m.active) revert ModuleInactive(moduleId);
        if (m.paused) revert ModulePaused(moduleId);
        _enforcePolicy(moduleId, user);

        // Mint cap: 0 == unlimited; otherwise post-deposit total must not exceed cap.
        if (m.mintCapEth != 0) {
            uint256 newTotal = IStakingModule(m.addr).totalEth() + amount;
            if (newTotal > m.mintCapEth) revert MintCapExceeded(moduleId, newTotal, m.mintCapEth);
        }

        _consumeInflow(moduleId, amount);

        // Compute shares BEFORE updating pool — pre-deposit exchange rate (no inflation).
        uint256 currentPooled = ST_TOKEN.totalPooledEther();
        uint256 currentShares = ST_TOKEN.getTotalShares();
        sharesAmount = ShareMath.getSharesByPooledEth(amount, currentShares, currentPooled);

        // Send ETH to the module first (Checks-Effects-Interactions-friendly: nonReentrant
        // and we mutate StToken state after this call. The module is trusted (registered
        // by GOV), and `receiveDeposit()` updates its internal buffer only.)
        IStakingModule(m.addr).receiveDeposit{value: amount}();

        // Increase totalPooledEther by deposit amount (the ETH is in the module).
        uint256 postDepositPooled = currentPooled + amount;
        uint256 globalCap = maxTotalPooledEther;
        if (globalCap != 0 && postDepositPooled > globalCap) {
            revert MaxTotalPooledExceeded(postDepositPooled, globalCap);
        }
        ST_TOKEN.setTotalPooledEther(postDepositPooled);
        ST_TOKEN.mintShares(user, sharesAmount);
        _recordReferral(user, referral, amount, sharesAmount);

        emit Deposited(moduleId, user, amount, sharesAmount, referral);
        if (emitAttribution) {
            emit DepositAttributed(moduleId, user, sourceId, amount, sharesAmount, referral);
        }
    }

    // ── Module-callback path: beacon-balance reports ─────────────────────────

    /// @inheritdoc IStakingRouter
    function reportModuleBeaconBalance(bytes32 moduleId, uint256 newBeaconBalance)
        external
        override
        nonReentrant
    {
        _requireModuleCaller(moduleId);
        uint256 prior = moduleBeaconBalance[moduleId];
        uint256 currentPooled = ST_TOKEN.totalPooledEther();
        moduleBeaconBalance[moduleId] = newBeaconBalance;
        int256 delta = _applyBeaconDelta(moduleId, prior, newBeaconBalance, currentPooled);

        emit ModuleBeaconReported(moduleId, newBeaconBalance, delta);
    }

    /// @inheritdoc IStakingRouter
    function notifyBeaconDeposit(bytes32 moduleId, uint256 amount) external override nonReentrant {
        _requireModuleCaller(moduleId);
        moduleBeaconBalance[moduleId] += amount;
        emit BeaconDepositNotified(moduleId, amount);
    }

    /// @inheritdoc IStakingRouter
    function wrapFromModule(bytes32 moduleId, address recipient, uint256 ethEquiv)
        external
        override
        nonReentrant
        whenNotPaused(PAUSE_SUBMIT)
    {
        ModuleInfo storage m = _requireModuleCaller(moduleId);
        if (!m.active) revert ModuleInactive(moduleId);
        if (m.paused) revert ModulePaused(moduleId);
        if (recipient == address(0)) revert Errors.ZeroAddress();
        if (ethEquiv == 0) revert Errors.InvalidAmount();
        _enforcePolicy(moduleId, recipient);

        if (m.mintCapEth != 0) {
            // For LST modules, totalEth() already reflects the new balance because the
            // module pulled the LST in before calling us. We compare directly to cap.
            uint256 newTotal = IStakingModule(m.addr).totalEth();
            if (newTotal > m.mintCapEth) revert MintCapExceeded(moduleId, newTotal, m.mintCapEth);
        }

        _consumeInflow(moduleId, ethEquiv);

        uint256 currentPooled = ST_TOKEN.totalPooledEther();
        uint256 currentShares = ST_TOKEN.getTotalShares();
        uint256 shares = ShareMath.getSharesByPooledEth(ethEquiv, currentShares, currentPooled);

        uint256 postWrapPooled = currentPooled + ethEquiv;
        uint256 globalCapWrap = maxTotalPooledEther;
        if (globalCapWrap != 0 && postWrapPooled > globalCapWrap) {
            revert MaxTotalPooledExceeded(postWrapPooled, globalCapWrap);
        }
        ST_TOKEN.setTotalPooledEther(postWrapPooled);
        ST_TOKEN.mintShares(recipient, shares);

        emit LSTWrapped(moduleId, recipient, ethEquiv, shares);
    }

    /// @inheritdoc IStakingRouter
    function unwrapToModule(bytes32 moduleId, address caller, uint256 stTokenAmount)
        external
        override
        nonReentrant
        returns (uint256 ethValue)
    {
        _requireModuleCaller(moduleId);
        if (caller == address(0)) revert Errors.ZeroAddress();
        if (stTokenAmount == 0) revert Errors.InvalidAmount();

        // Compute shares from token amount at current exchange rate.
        uint256 shares = ST_TOKEN.getSharesByPooledEth(stTokenAmount);
        if (shares == 0) revert Errors.InvalidAmount();
        ethValue = ST_TOKEN.getPooledEthByShares(shares);

        // Burn the shares from the original LST holder, reduce the pool to keep rate.
        uint256 currentPooled = ST_TOKEN.totalPooledEther();
        ST_TOKEN.burnShares(caller, shares);
        if (currentPooled >= ethValue) {
            ST_TOKEN.setTotalPooledEther(currentPooled - ethValue);
        } else {
            ST_TOKEN.setTotalPooledEther(0);
        }

        emit LSTUnwrapped(moduleId, caller, stTokenAmount, ethValue);
    }

    // ── Fee distribution (mirrors StakingCore behaviour for parity) ──────────

    function _distributeFees(bytes32 moduleId, uint256 rewards, uint256 newTotalPooled) internal {
        (, , , address treasury, address operator, address referralRegistry) = feeController.getFeeConfig();

        (uint256 treasuryAmount, uint256 operatorAmount, uint256 referralAmount) = feeController.computeFees(rewards);
        if (referralRegistry == address(0)) {
            referralAmount = 0;
        }
        if (treasuryAmount == 0 && operatorAmount == 0 && referralAmount == 0) return;

        uint256 totalFee = treasuryAmount + operatorAmount + referralAmount;
        uint256 newTotalShares = ST_TOKEN.getTotalShares();

        // Keep pool accounting strictly tied to real backing (buffer + beacon).
        // Fee recipients are paid via share dilution from existing rewards.

        // Mint fee shares at post-rebase rate so recipients capture exactly their cut.
        uint256 treasuryShares = ShareMath.getSharesByPooledEth(treasuryAmount, newTotalShares, newTotalPooled);
        uint256 operatorShares = ShareMath.getSharesByPooledEth(operatorAmount, newTotalShares, newTotalPooled);
        uint256 referralShares = ShareMath.getSharesByPooledEth(referralAmount, newTotalShares, newTotalPooled);

        if (treasuryShares > 0) ST_TOKEN.mintShares(treasury, treasuryShares);
        if (operatorShares > 0) ST_TOKEN.mintShares(operator, operatorShares);
        if (referralRegistry != address(0) && referralShares > 0) {
            ST_TOKEN.mintShares(referralRegistry, referralShares);
            IReferralRegistry(referralRegistry).depositReferralFeeShares(referralShares);
        }

        emit FeeSharesMinted(treasury, treasuryShares, operator, operatorShares);
        FeeRoutingData memory routing = FeeRoutingData({
            rewards: 0,
            treasuryAmount: 0,
            operatorAmount: 0,
            treasuryShares: 0,
            operatorShares: 0,
            totalFeeAmount: 0,
            totalPooledBeforeFees: 0,
            totalPooledAfterFees: 0
        });
        routing.rewards = rewards;
        routing.treasuryAmount = treasuryAmount;
        routing.operatorAmount = operatorAmount;
        routing.treasuryShares = treasuryShares;
        routing.operatorShares = operatorShares;
        routing.totalFeeAmount = totalFee;
        routing.totalPooledBeforeFees = newTotalPooled;
        routing.totalPooledAfterFees = newTotalPooled; // pool stays at real backing
        _emitFeeRoutingTelemetry(moduleId, routing);
    }

    function _recordReferral(address user, address referral, uint256 amount, uint256 sharesAmount) internal {
        if (referral == address(0) || address(feeController) == address(0)) return;
        (, , , , , address referralRegistry) = feeController.getFeeConfig();
        if (referralRegistry == address(0)) return;
        IReferralRegistry(referralRegistry).recordDeposit(referral, user, amount, sharesAmount);
    }

    function _emitFeeRoutingTelemetry(bytes32 moduleId, FeeRoutingData memory routing) internal {
        emit FeeRoutingTelemetry(
            moduleId,
            routing.rewards,
            routing.treasuryAmount,
            routing.operatorAmount,
            routing.treasuryShares,
            routing.operatorShares,
            routing.totalFeeAmount,
            routing.totalPooledBeforeFees,
            routing.totalPooledAfterFees
        );
    }

    function _consumeInflow(bytes32 moduleId, uint256 amount) internal {
        InflowLimitConfig storage cfg = moduleInflowLimitConfig[moduleId];
        if (cfg.windowSeconds == 0 || cfg.maxInflowEthPerWindow == 0) {
            return;
        }

        InflowWindowState storage windowState = moduleInflowWindowState[moduleId];
        if (windowState.windowStart == 0 || block.timestamp - windowState.windowStart >= cfg.windowSeconds) {
            windowState.windowStart = block.timestamp;
            windowState.inflowEth = 0;
        }

        uint256 newInflow = windowState.inflowEth + amount;
        if (newInflow > cfg.maxInflowEthPerWindow) {
            revert InflowLimitExceeded(moduleId, newInflow, cfg.maxInflowEthPerWindow);
        }

        windowState.inflowEth = newInflow;
    }

    function _requireModuleCaller(bytes32 moduleId) internal view returns (ModuleInfo storage m) {
        m = _modules[moduleId];
        if (m.addr == address(0)) revert ModuleNotRegistered(moduleId);
        if (msg.sender != m.addr) revert NotModule(moduleId, msg.sender);
    }

    function _applyBeaconDelta(bytes32 moduleId, uint256 prior, uint256 newBeaconBalance, uint256 currentPooled)
        internal
        returns (int256 delta)
    {
        if (newBeaconBalance >= prior) {
            uint256 gain = newBeaconBalance - prior;
            if (gain == 0) return 0;

            _enforceBeaconGainSanity(moduleId, prior, gain, newBeaconBalance);
            uint256 postPool = currentPooled + gain;
            ST_TOKEN.setTotalPooledEther(postPool);
            if (address(feeController) != address(0)) {
                _distributeFees(moduleId, gain, postPool);
            }
            return int256(gain);
        }

        uint256 loss = prior - newBeaconBalance;
        // Explicit branch on insolvency so we leave a trace before clamping to 0.
        if (currentPooled <= loss) {
            emit PoolInsolvent(moduleId, loss, currentPooled);
            ST_TOKEN.setTotalPooledEther(0);
        } else {
            ST_TOKEN.setTotalPooledEther(currentPooled - loss);
        }
        return -int256(loss);
    }

    function _enforceBeaconGainSanity(bytes32 moduleId, uint256 prior, uint256 gain, uint256 newBeaconBalance)
        internal
        view
    {
        // Require module baseline initialization via notifyBeaconDeposit before
        // any positive report to prevent counting principal as rewards.
        if (prior == 0) revert BeaconBaselineNotInitialized(moduleId, newBeaconBalance);

        uint256 gainBps = (gain * 10000) / prior;
        if (gainBps > maxDeltaBps) {
            revert BeaconReportSanityFailed(moduleId, gainBps, maxDeltaBps);
        }
    }

    function _enforcePolicy(bytes32 moduleId, address account) internal view {
        IInstitutionalPolicyRegistry registry = policyRegistry;
        bytes32 policyId = modulePolicyId[moduleId];
        if (address(registry) == address(0) || policyId == bytes32(0)) {
            return;
        }
        if (!registry.isAllowed(policyId, account)) {
            revert PolicyDenied(moduleId, policyId, account);
        }
    }

    // ── GOV: module registry ──────────────────────────────────────────────────

    function registerModule(bytes32 moduleId, address moduleAddr, uint256 mintCapEth)
        external
        onlyRole(GOV)
    {
        if (moduleId == bytes32(0)) revert Errors.InvalidAmount();
        if (moduleAddr == address(0)) revert Errors.ZeroAddress();
        if (_modules[moduleId].addr != address(0)) revert ModuleAlreadyRegistered(moduleId);

        bytes32 mType = IStakingModule(moduleAddr).moduleType();
        _modules[moduleId] = ModuleInfo({
            addr: moduleAddr,
            moduleType: mType,
            mintCapEth: mintCapEth,
            active: true,
            paused: false
        });
        emit ModuleRegistered(moduleId, moduleAddr, mType, mintCapEth);
    }

    function setMintCap(bytes32 moduleId, uint256 mintCapEth) external onlyRole(GOV) {
        ModuleInfo storage m = _modules[moduleId];
        if (m.addr == address(0)) revert ModuleNotRegistered(moduleId);
        m.mintCapEth = mintCapEth;
        emit ModuleMintCapSet(moduleId, mintCapEth);
    }

    /// @notice Configure optional per-module inflow limiter.
    /// @dev Disabled whenever `windowSeconds == 0` or `maxInflowEthPerWindow == 0`.
    function setModuleInflowLimit(bytes32 moduleId, uint256 windowSeconds, uint256 maxInflowEthPerWindow)
        external
        onlyRole(GOV)
    {
        ModuleInfo storage m = _modules[moduleId];
        if (m.addr == address(0)) revert ModuleNotRegistered(moduleId);

        moduleInflowLimitConfig[moduleId] = InflowLimitConfig({
            windowSeconds: windowSeconds,
            maxInflowEthPerWindow: maxInflowEthPerWindow
        });
        delete moduleInflowWindowState[moduleId];
        emit ModuleInflowLimitSet(moduleId, windowSeconds, maxInflowEthPerWindow);
    }

    /// @notice Set or clear institutional policy registry. Zero address disables policy checks.
    function setPolicyRegistry(address registry) external onlyRole(GOV) {
        policyRegistry = IInstitutionalPolicyRegistry(registry);
        emit PolicyRegistrySet(registry);
    }

    /// @notice Assign policy id for a module. Set to zero bytes32 to disable module-level policy checks.
    function setModulePolicy(bytes32 moduleId, bytes32 policyId) external onlyRole(GOV) {
        ModuleInfo storage m = _modules[moduleId];
        if (m.addr == address(0)) revert ModuleNotRegistered(moduleId);
        modulePolicyId[moduleId] = policyId;
        emit ModulePolicySet(moduleId, policyId);
    }

    function setDefaultModule(bytes32 moduleId) external onlyRole(GOV) {
        ModuleInfo storage m = _modules[moduleId];
        if (m.addr == address(0)) revert ModuleNotRegistered(moduleId);
        defaultModuleId = moduleId;
        emit DefaultModuleSet(moduleId);
    }

    function pauseModule(bytes32 moduleId) external onlyRole(GUARDIAN) {
        ModuleInfo storage m = _modules[moduleId];
        if (m.addr == address(0)) revert ModuleNotRegistered(moduleId);
        m.paused = true;
        emit ModulePausedSet(moduleId, true);
    }

    function unpauseModule(bytes32 moduleId) external onlyRole(GOV) {
        ModuleInfo storage m = _modules[moduleId];
        if (m.addr == address(0)) revert ModuleNotRegistered(moduleId);
        m.paused = false;
        emit ModulePausedSet(moduleId, false);
    }

    function setFeeController(address fc) external onlyRole(GOV) {
        if (fc == address(0)) revert Errors.ZeroAddress();
        feeController = FeeController(fc);
        emit FeeControllerSet(fc);
    }

    /// @notice Update the per-report sanity bound on beacon-balance gains.
    /// @param bps New maximum gain in basis points (10000 = 100%).
    ///         Hard ceiling at 1000 (10%) to prevent runaway inflation.
    ///         Values above 1000 revert regardless of GOV.
    function setMaxDeltaBps(uint256 bps) external onlyRole(GOV) {
        if (bps > 1000) revert Errors.InvalidAmount();
        maxDeltaBps = bps;
        emit MaxDeltaBpsSet(bps);
    }

    /// @notice Set a global cap on totalPooledEther. 0 = unlimited.
    /// @param cap New maximum total pooled ETH in wei.
    function setMaxTotalPooledEther(uint256 cap) external onlyRole(GOV) {
        maxTotalPooledEther = cap;
        emit MaxTotalPooledEtherSet(cap);
    }

    // ── GUARDIAN: pause hub ──────────────────────────────────────────────────

    function pause(uint16 fnId) external onlyRole(GUARDIAN) {
        _pause(fnId);
    }

    function unpause(uint16 fnId) external onlyRole(GOV) {
        _unpause(fnId);
    }

    /// @notice Emergency: pause submit AND every registered module flag.
    /// @dev Iterates a caller-supplied list; we don't store enumerable list to keep storage lean.
    function emergencyPauseAll(bytes32[] calldata moduleIds) external onlyRole(GUARDIAN) {
        _pause(PAUSE_SUBMIT);
        for (uint256 i; i < moduleIds.length; ++i) {
            ModuleInfo storage m = _modules[moduleIds[i]];
            if (m.addr != address(0)) {
                m.paused = true;
                emit ModulePausedSet(moduleIds[i], true);
            }
        }
    }

    // ── Views ────────────────────────────────────────────────────────────────

    /// @inheritdoc IStakingRouter
    function modules(bytes32 moduleId)
        external
        view
        override
        returns (address addr, bytes32 moduleType, uint256 mintCapEth, bool active, bool paused)
    {
        ModuleInfo storage m = _modules[moduleId];
        return (m.addr, m.moduleType, m.mintCapEth, m.active, m.paused);
    }

    /// @notice ETH attributable to the system, summed across an explicit list of modules.
    ///         Off-chain observers compute this by enumerating ModuleRegistered events.
    function totalEthOf(bytes32[] calldata ids) external view returns (uint256 sum) {
        for (uint256 i; i < ids.length; ++i) {
            address a = _modules[ids[i]].addr;
            if (a != address(0)) sum += IStakingModule(a).totalEth();
        }
    }
}

contracts/v2/modular-staking/StEthPriceO.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

import {ILSTPriceOracle} from "./interfaces/ILSTPriceOracle.sol";
import {Errors} from "../lib/Errors.sol";

/// @title StEthPriceOracle - reference ILSTPriceOracle for stETH
/// @notice Reads stETH's per-share pooled ETH directly from the source protocol. Since
///         stETH balances ARE ETH-denominated (rebasing), the price function is the
///         identity 1:1 in normal conditions; we still route through the stETH contract
///         so this oracle can be swapped for a wstETH-style one without touching
///         consumers.
interface IStEth {
    function getPooledEthByShares(uint256 sharesAmount) external view returns (uint256);
    function getSharesByPooledEth(uint256 ethAmount) external view returns (uint256);
}

contract StEthPriceOracle is ILSTPriceOracle {
    IStEth public immutable ST_ETH;

    constructor(address stEth) {
        if (stEth == address(0)) revert Errors.ZeroAddress();
        ST_ETH = IStEth(stEth);
    }

    /// @inheritdoc ILSTPriceOracle
    /// @dev For stETH: 1 stETH ≈ 1 ETH (rebasing). The LST balance IS the ETH backing
    ///      net of slashings. Returning the LST amount as ETH equivalent is correct
    ///      for stETH-denominated holdings.
    function getEthValue(uint256 lstAmount) external view override returns (uint256) {
        // Round-trip via shares to reflect the precise current rebase rate.
        uint256 shares = ST_ETH.getSharesByPooledEth(lstAmount);
        return ST_ETH.getPooledEthByShares(shares);
    }

    /// @inheritdoc ILSTPriceOracle
    function getLstValue(uint256 ethAmount) external view override returns (uint256) {
        // Same round-trip in the inverse direction.
        uint256 shares = ST_ETH.getSharesByPooledEth(ethAmount);
        return ST_ETH.getPooledEthByShares(shares);
    }

    /// @inheritdoc ILSTPriceOracle
    /// @dev This oracle reads the live stETH contract on every call, so the price is
    ///      always as fresh as the latest on-chain oracle/rebase update reflected on-chain.
    ///      Returning `block.timestamp` makes any reasonable staleness check pass while
    ///      still letting consumers wire the same guard they would use against a
    ///      push-style oracle. If a future implementation caches values, replace this
    ///      with the timestamp of the cached read.
    function lastUpdated() external view override returns (uint256) {
        return block.timestamp;
    }
}

contracts/v2/modular-staking/StToken.sol.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import {ERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {ShareMath} from "./ShareMath.sol";
import {Errors} from "../lib/Errors.sol";

/// @title StToken - rebasing staked-ETH token (stETH parity)
/// @notice Balances rebase automatically when oracle reports new pooled ETH.
///         Under the hood, the contract stores shares. The rebasing balance is:
///             balanceOf(account) = sharesOf(account) * totalPooledEther / totalShares
/// @dev EIP-712 permit supported (inherited via ERC20Permit initialisation).
///      ERC20 events are emitted with token amounts, not share amounts.
///      TransferShares events provide the share-level view.
contract StToken is AccessControl, ReentrancyGuard {
    using ShareMath for *;

    // ── Roles ────────────────────────────────────────────────────────────────
    bytes32 public constant MINTER = keccak256("MINTER");
    bytes32 public constant GOV = keccak256("GOV");

    // ── State ─────────────────────────────────────────────────────────────────
    string public constant name = "SharedStake Staked Ether";
    string public constant symbol = "stETH";
    uint8 public constant decimals = 18;

    uint256 private _totalShares;
    uint256 private _totalPooledEther;

    mapping(address => uint256) private _sharesOf;
    /// @notice Token-denominated allowances (not share-denominated; mirrors ERC20 convention).
    mapping(address => mapping(address => uint256)) private _allowances;

    // ── Events ────────────────────────────────────────────────────────────────
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event TransferShares(address indexed from, address indexed to, uint256 sharesValue);
    event SharesMinted(address indexed account, uint256 tokenAmount, uint256 sharesAmount);
    event SharesBurned(address indexed account, uint256 tokenAmount, uint256 sharesAmount);
    event TotalPooledEtherUpdated(uint256 preTotalPooledEther, uint256 postTotalPooledEther);

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    // ── ERC20 surface ─────────────────────────────────────────────────────────

    function totalSupply() external view returns (uint256) {
        return _totalPooledEther;
    }

    function balanceOf(address account) external view returns (uint256) {
        return ShareMath.getPooledEthByShares(_sharesOf[account], _totalShares, _totalPooledEther);
    }

    function allowance(address owner, address spender) external view returns (uint256) {
        return _allowances[owner][spender];
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        _approve(msg.sender, spender, amount);
        return true;
    }

    function transfer(address to, uint256 amount) external nonReentrant returns (bool) {
        _transfer(msg.sender, to, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external nonReentrant returns (bool) {
        uint256 currentAllowance = _allowances[from][msg.sender];
        if (currentAllowance != type(uint256).max) {
            if (currentAllowance < amount) revert Errors.InsufficientAllowance();
            unchecked {
                _approve(from, msg.sender, currentAllowance - amount);
            }
        }
        _transfer(from, to, amount);
        return true;
    }

    // ── Share-aware functions ─────────────────────────────────────────────────

    function sharesOf(address account) external view returns (uint256) {
        return _sharesOf[account];
    }

    function getTotalShares() external view returns (uint256) {
        return _totalShares;
    }

    function totalPooledEther() external view returns (uint256) {
        return _totalPooledEther;
    }

    function getSharesByPooledEth(uint256 ethAmount) external view returns (uint256) {
        return ShareMath.getSharesByPooledEth(ethAmount, _totalShares, _totalPooledEther);
    }

    function getPooledEthByShares(uint256 sharesAmount) external view returns (uint256) {
        return ShareMath.getPooledEthByShares(sharesAmount, _totalShares, _totalPooledEther);
    }

    /// @notice Transfer by share amount rather than token amount.
    function transferShares(address to, uint256 sharesAmount) external returns (uint256 tokensAmount) {
        tokensAmount = ShareMath.getPooledEthByShares(sharesAmount, _totalShares, _totalPooledEther);
        _transferShares(msg.sender, to, sharesAmount);
        emit Transfer(msg.sender, to, tokensAmount);
    }

    // ── Privileged: share supply management ──────────────────────────────────

    /// @notice Mint shares to `recipient`. Called by StakingCore on deposit.
    function mintShares(address recipient, uint256 sharesAmount) external onlyRole(MINTER) {
        if (recipient == address(0)) revert Errors.ZeroAddress();
        if (sharesAmount == 0) revert Errors.InvalidAmount();

        _sharesOf[recipient] += sharesAmount;
        _totalShares += sharesAmount;

        uint256 tokenAmount = ShareMath.getPooledEthByShares(sharesAmount, _totalShares, _totalPooledEther);
        emit SharesMinted(recipient, tokenAmount, sharesAmount);
        emit Transfer(address(0), recipient, tokenAmount);
    }

    /// @notice Burn shares from `account`. Called by StakingCore on withdrawal.
    function burnShares(address account, uint256 sharesAmount) external onlyRole(MINTER) {
        if (sharesAmount == 0) revert Errors.InvalidAmount();
        if (_sharesOf[account] < sharesAmount) revert Errors.InsufficientBalance();

        uint256 tokenAmount = ShareMath.getPooledEthByShares(sharesAmount, _totalShares, _totalPooledEther);
        _sharesOf[account] -= sharesAmount;
        _totalShares -= sharesAmount;

        emit SharesBurned(account, tokenAmount, sharesAmount);
        emit Transfer(account, address(0), tokenAmount);
    }

    /// @notice Called by StakingCore when oracle reports new beacon balance (reward rebase).
    function setTotalPooledEther(uint256 newTotalPooledEther) external onlyRole(MINTER) {
        emit TotalPooledEtherUpdated(_totalPooledEther, newTotalPooledEther);
        _totalPooledEther = newTotalPooledEther;
    }

    // ── Admin ─────────────────────────────────────────────────────────────────

    function addMinter(address minter) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (minter == address(0)) revert Errors.ZeroAddress();
        grantRole(MINTER, minter);
    }

    function removeMinter(address minter) external onlyRole(DEFAULT_ADMIN_ROLE) {
        revokeRole(MINTER, minter);
    }

    function transferAdmin(address newAdmin) external onlyRole(DEFAULT_ADMIN_ROLE) {
        if (newAdmin == address(0)) revert Errors.ZeroAddress();
        // Clean up MINTER role from old admin before transferring DEFAULT_ADMIN_ROLE
        if (hasRole(MINTER, msg.sender)) {
            renounceRole(MINTER, msg.sender);
        }
        grantRole(DEFAULT_ADMIN_ROLE, newAdmin);
        renounceRole(DEFAULT_ADMIN_ROLE, msg.sender);
    }

    // ── Internal ──────────────────────────────────────────────────────────────

    function _transfer(address from, address to, uint256 amount) internal {
        if (to == address(0)) revert Errors.ZeroAddress();
        uint256 shares = ShareMath.getSharesByPooledEth(amount, _totalShares, _totalPooledEther);
        if (shares == 0) revert Errors.InvalidAmount();
        _transferShares(from, to, shares);
        emit Transfer(from, to, amount);
    }

    function _transferShares(address from, address to, uint256 sharesAmount) internal {
        if (_sharesOf[from] < sharesAmount) revert Errors.InsufficientBalance();
        unchecked {
            _sharesOf[from] -= sharesAmount;
        }
        _sharesOf[to] += sharesAmount;
        emit TransferShares(from, to, sharesAmount);
    }

    function _approve(address owner, address spender, uint256 amount) internal {
        _allowances[owner][spender] = amount;
        emit Approval(owner, spender, amount);
    }
}

contracts/v2/modular-staking/WithdrawalQ.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import {Address} from "@openzeppelin/contracts/utils/Address.sol";
import {StToken} from "./StToken.sol";
import {Errors} from "../lib/Errors.sol";

/// @title WithdrawalQueueV2 - SharedStake V2 withdrawal queue
/// @notice Three-step lifecycle:
///   1. requestWithdrawals  — user burns stToken shares, obtains requestId(s)
///   2. finalize            — guardian finalizes a batch, providing ETH at the agreed share rate
///   3. claimWithdrawal     — request owner withdraws their ETH
///
/// Invariants maintained:
///   - No request can claim more ETH than it contributed shares × finalized share rate.
///   - Once finalized, the ETH for a batch is locked and cannot be redirected.
///   - Claimed flag prevents replay.
///
/// Safety: the contract accepts ETH during finalize so it can hold funds between finalize and claim.
contract WithdrawalQueueV2 is AccessControl, ReentrancyGuard {
    using Address for address payable;

    // ── Roles ─────────────────────────────────────────────────────────────────
    bytes32 public constant GOV = keccak256("GOV");
    bytes32 public constant ORACLE = keccak256("ORACLE");
    bytes32 public constant GUARDIAN = keccak256("GUARDIAN");

    // ── Types ─────────────────────────────────────────────────────────────────
    enum WithdrawalMode {
        TURBO,
        BUNKER
    }

    struct WithdrawalRequest {
        address owner;
        uint256 stShares;          // shares burned at request time
        uint256 ethAmount;         // ETH owed — set during finalize
        uint256 requestedAt;       // request creation timestamp
        bool finalized;
        bool claimed;
    }

    // ── State ─────────────────────────────────────────────────────────────────
    StToken public immutable ST_TOKEN;

    uint256 public nextRequestId = 1;
    uint256 public lastFinalizedRequestId; // inclusive upper bound of finalized range

    mapping(uint256 => WithdrawalRequest) public requests;

    // ETH locked for finalized-but-unclaimed requests.
    uint256 public lockedEther;

    // Queue finalization mode is oracle-controlled.
    WithdrawalMode public withdrawalMode;
    uint256 public lastOracleReportTimestamp;

    // Bunker mode finalize guardrails.
    uint256 public bunkerMaxRequestsPerFinalize = 16;
    uint256 public bunkerMinRequestAge = 1 days;

    // ── Limits ────────────────────────────────────────────────────────────────
    uint256 public constant MIN_WITHDRAWAL = 0.01 ether;
    uint256 public constant MAX_WITHDRAWAL = 1000 ether;

    // ── Events ────────────────────────────────────────────────────────────────
    event WithdrawalRequested(
        address indexed owner,
        uint256 indexed requestId,
        uint256 stShares,
        uint256 stTokenAmount
    );
    event BatchFinalized(uint256 indexed fromRequestId, uint256 indexed toRequestId, uint256 ethProvided);
    event WithdrawalClaimed(address indexed owner, address indexed recipient, uint256 indexed requestId, uint256 ethAmount);
    event WithdrawalCancelled(address indexed owner, uint256 indexed requestId, uint256 stShares);
    event WithdrawalModeUpdated(WithdrawalMode mode, uint256 reportTimestamp);
    event BunkerParamsUpdated(uint256 bunkerMaxRequestsPerFinalize, uint256 bunkerMinRequestAge);

    // ── Errors ────────────────────────────────────────────────────────────────
    error RequestNotFinalized(uint256 requestId);
    error RequestAlreadyClaimed(uint256 requestId);
    error NotRequestOwner(uint256 requestId, address caller);
    error AmountOutOfBounds(uint256 amount);
    error InsufficientFinalizeEth(uint256 required, uint256 provided);
    error InvalidRequestRange(uint256 from, uint256 to);
    error BunkerBatchTooLarge(uint256 requested, uint256 maxAllowed);
    error RequestTooYoung(uint256 requestId, uint256 requestTimestamp, uint256 minFinalizableTimestamp);
    error InvalidBunkerParam();
    error InvalidReportTimestamp(uint256 reportTimestamp, uint256 currentTimestamp);

    constructor(address stToken, address gov) {
        if (stToken == address(0) || gov == address(0)) revert Errors.ZeroAddress();
        ST_TOKEN = StToken(stToken);
        _grantRole(DEFAULT_ADMIN_ROLE, gov);
        _grantRole(GOV, gov);
        _grantRole(ORACLE, gov);
        _grantRole(GUARDIAN, gov);
    }

    // ── Request ───────────────────────────────────────────────────────────────

    /// @notice Burn stTokens and enqueue withdrawal requests.
    /// @param amounts  Array of stToken amounts to withdraw (each entry = one request).
    /// @param owner    Address that will own the requests and can claim ETH.
    /// @return requestIds Assigned request IDs.
    function requestWithdrawals(uint256[] calldata amounts, address owner)
        external
        nonReentrant
        returns (uint256[] memory requestIds)
    {
        if (owner == address(0)) revert Errors.ZeroAddress();

        requestIds = new uint256[](amounts.length);
        for (uint256 i; i < amounts.length; ++i) {
            requestIds[i] = _enqueueRequest(amounts[i], owner);
        }
    }

    function _enqueueRequest(uint256 stTokenAmount, address owner) internal returns (uint256 requestId) {
        if (stTokenAmount < MIN_WITHDRAWAL || stTokenAmount > MAX_WITHDRAWAL) {
            revert AmountOutOfBounds(stTokenAmount);
        }

        uint256 shares = ST_TOKEN.getSharesByPooledEth(stTokenAmount);
        if (shares == 0) revert Errors.InvalidAmount();

        // Compute exact ETH value at current exchange rate before burning.
        // Stored so finalization doesn't require a separate rate parameter.
        uint256 ethValue = ST_TOKEN.getPooledEthByShares(shares);

        // Reduce totalPooledEther BEFORE burning shares to keep exchange rate
        // consistent throughout the transaction (atomic state update).
        uint256 currentPooled = ST_TOKEN.totalPooledEther();
        if (currentPooled >= ethValue) {
            ST_TOKEN.setTotalPooledEther(currentPooled - ethValue);
        }
        ST_TOKEN.burnShares(msg.sender, shares);

        requestId = nextRequestId++;
        requests[requestId] = WithdrawalRequest({
            owner: owner,
            stShares: shares,
            ethAmount: ethValue,  // locked at request-time exchange rate
            requestedAt: block.timestamp,
            finalized: false,
            claimed: false
        });

        emit WithdrawalRequested(owner, requestId, shares, stTokenAmount);
    }

    // ── Finalize ──────────────────────────────────────────────────────────────

    /// @notice Finalize all pending requests up to and including `lastRequestId`.
    ///         Caller must send at least enough ETH to cover the sum of request ethAmounts.
    ///         ETH amounts were locked at request time; no share rate recalculation here.
    /// @param lastRequestId Last request ID to finalize (inclusive).
    function finalize(uint256 lastRequestId)
        external
        payable
        onlyRole(GUARDIAN)
        nonReentrant
    {
        uint256 fromId = lastFinalizedRequestId + 1;
        if (lastRequestId < fromId || lastRequestId >= nextRequestId) {
            revert InvalidRequestRange(fromId, lastRequestId);
        }
        uint256 requestsCount = lastRequestId - fromId + 1;
        bool bunkerModeActive = withdrawalMode == WithdrawalMode.BUNKER;
        if (bunkerModeActive && requestsCount > bunkerMaxRequestsPerFinalize) {
            revert BunkerBatchTooLarge(requestsCount, bunkerMaxRequestsPerFinalize);
        }

        uint256 totalEthRequired = 0;
        for (uint256 id = fromId; id <= lastRequestId; ++id) {
            WithdrawalRequest storage req = requests[id];
            if (bunkerModeActive) {
                uint256 minFinalizableTimestamp = req.requestedAt + bunkerMinRequestAge;
                if (lastOracleReportTimestamp < minFinalizableTimestamp) {
                    revert RequestTooYoung(id, req.requestedAt, minFinalizableTimestamp);
                }
            }
            req.finalized = true;
            totalEthRequired += req.ethAmount; // ethAmount locked at request time
        }

        if (msg.value < totalEthRequired) {
            revert InsufficientFinalizeEth(totalEthRequired, msg.value);
        }

        lockedEther += totalEthRequired;
        lastFinalizedRequestId = lastRequestId;

        // Return any excess ETH to the caller.
        if (msg.value > totalEthRequired) {
            payable(msg.sender).sendValue(msg.value - totalEthRequired);
        }

        emit BatchFinalized(fromId, lastRequestId, totalEthRequired);
    }

    // ── Oracle mode update ────────────────────────────────────────────────────

    /// @notice Update queue mode from oracle report context.
    /// @param isBunkerMode Whether bunker mode should be active.
    /// @param reportTimestamp Oracle report timestamp used for age-based finalization checks.
    function updateModeFromOracle(bool isBunkerMode, uint256 reportTimestamp)
        external
        onlyRole(ORACLE)
    {
        if (reportTimestamp > block.timestamp) {
            revert InvalidReportTimestamp(reportTimestamp, block.timestamp);
        }
        withdrawalMode = isBunkerMode ? WithdrawalMode.BUNKER : WithdrawalMode.TURBO;
        lastOracleReportTimestamp = reportTimestamp;
        emit WithdrawalModeUpdated(withdrawalMode, reportTimestamp);
    }

    // ── Gov setters ───────────────────────────────────────────────────────────

    function setBunkerMaxRequestsPerFinalize(uint256 maxRequests) external onlyRole(GOV) {
        if (maxRequests == 0) revert InvalidBunkerParam();
        bunkerMaxRequestsPerFinalize = maxRequests;
        emit BunkerParamsUpdated(bunkerMaxRequestsPerFinalize, bunkerMinRequestAge);
    }

    function setBunkerMinRequestAge(uint256 minAge) external onlyRole(GOV) {
        bunkerMinRequestAge = minAge;
        emit BunkerParamsUpdated(bunkerMaxRequestsPerFinalize, bunkerMinRequestAge);
    }

    /// @notice Recover accidentally sent ETH that is not locked for claims.
    function recoverEth(address payable to, uint256 amount) external onlyRole(GOV) {
        uint256 available = address(this).balance - lockedEther;
        if (amount > available) revert Errors.InsufficientBalance();
        to.sendValue(amount);
    }

    // ── Claim ─────────────────────────────────────────────────────────────────

    /// @notice Claim ETH for a finalized withdrawal request.
    /// @param requestId  The request to claim.
    /// @param recipient  Address to send ETH to.
    function claimWithdrawal(uint256 requestId, address payable recipient)
        external
        nonReentrant
    {
        WithdrawalRequest storage req = requests[requestId];

        if (!req.finalized) revert RequestNotFinalized(requestId);
        if (req.claimed) revert RequestAlreadyClaimed(requestId);
        if (req.owner != msg.sender) revert NotRequestOwner(requestId, msg.sender);
        if (recipient == address(0)) revert Errors.ZeroAddress();

        req.claimed = true;
        uint256 ethAmount = req.ethAmount;
        lockedEther -= ethAmount;

        recipient.sendValue(ethAmount);
        emit WithdrawalClaimed(msg.sender, recipient, requestId, ethAmount);
    }

    /// @notice Batch claim multiple finalized requests in one transaction.
    function claimWithdrawals(uint256[] calldata requestIds, address payable recipient)
        external
        nonReentrant
    {
        if (recipient == address(0)) revert Errors.ZeroAddress();
        uint256 totalEth = 0;
        for (uint256 i; i < requestIds.length; ++i) {
            uint256 id = requestIds[i];
            WithdrawalRequest storage req = requests[id];

            if (!req.finalized) revert RequestNotFinalized(id);
            if (req.claimed) revert RequestAlreadyClaimed(id);
            if (req.owner != msg.sender) revert NotRequestOwner(id, msg.sender);

            req.claimed = true;
            totalEth += req.ethAmount;
            emit WithdrawalClaimed(msg.sender, recipient, id, req.ethAmount);
        }
        lockedEther -= totalEth;
        recipient.sendValue(totalEth);
    }

    // ── Views ─────────────────────────────────────────────────────────────────

    function getRequest(uint256 requestId) external view returns (WithdrawalRequest memory) {
        return requests[requestId];
    }

    function getRequestStatus(uint256 requestId)
        external
        view
        returns (bool finalized, bool claimed, uint256 ethAmount)
    {
        WithdrawalRequest storage req = requests[requestId];
        return (req.finalized, req.claimed, req.ethAmount);
    }

    /// @notice ETH available in this contract (total balance minus locked-for-claims).
    function availableEther() external view returns (uint256) {
        return address(this).balance - lockedEther;
    }

    /// @notice Accept plain ETH deposits (e.g., from StakingCore funding withdrawal queue).
    receive() external payable {}
}

